package com.logadviser;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(LogAdviserConfig.GROUP)
public interface LogAdviserConfig extends Config
{
	String GROUP = "logadviser";

	enum DisplayMode
	{
		INFOBOX("Info box (top-left tray)"),
		OVERLAY_PANEL("Overlay box"),
		BOTH("Both"),
		NONE("None");

		private final String label;

		DisplayMode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}

		public boolean infoBox()
		{
			return this == INFOBOX || this == BOTH;
		}

		public boolean overlayPanel()
		{
			return this == OVERLAY_PANEL || this == BOTH;
		}
	}

	@ConfigItem(
		keyName = "displayMode",
		name = "Show next slot as",
		description = "Where to surface the next collection log target. The info box lives in the top-left tray; the overlay box renders on top of the game viewport.",
		position = 1
	)
	default DisplayMode displayMode()
	{
		return DisplayMode.INFOBOX;
	}

	@ConfigItem(
		keyName = "upcomingListSize",
		name = "Upcoming list size",
		description = "Number of upcoming activities shown in the sidebar list.",
		position = 2
	)
	default int upcomingListSize()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "disableHover",
		name = "Disable hover preview",
		description = "Stop showing the pop-up list of an activity's log slots when hovering rows in the sidebar panel.",
		position = 3
	)
	default boolean disableHover()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hideSyncButton",
		name = "Hide Log Sync button",
		description = "Stop adding the \"Log Sync\" button to the in-game Collection Log header. "
			+ "New drops are still tracked from chat, but a full sync is unavailable while hidden.",
		position = 4
	)
	default boolean hideSyncButton()
	{
		return false;
	}

	// How-to-sync guidance. Same empty-section trick as infoSection below: an item-less
	// @ConfigSection still renders its header, so the HTML name carries the instruction.
	@ConfigSection(
		name = "<html>Syncing your collection log<br>"
			+ "Open the Collection Log in-game and click the<br>"
			+ "\"Log Sync\" button in its header to sync your data</html>",
		description = "Open your in-game Collection Log and click the \"Log Sync\" button in the "
			+ "header to bring Log Adviser up to date with your obtained slots.",
		position = 99,
		closedByDefault = true
	)
	String syncSection = "syncSection";

	// Standing guidance placed BELOW the options. Kept as an empty section at the bottom: RuneLite
	// builds every section into the config panel regardless of whether it holds items, so the header
	// renders on its own. The name is HTML so the JLabel wraps it across lines instead of clipping,
	// and closedByDefault leaves no empty expanded area under it — just the wrapping text.
	@ConfigSection(
		name = "<html>To see the complete list and more functionalities<br>"
			+ "open the side bar panel with the collection log book<br>"
			+ "icon on the right side</html>",
		description = "Open the Log Adviser side panel (collection log book icon) for the full "
			+ "ranked activity list, hover previews, the skip list and more.",
		position = 100,
		closedByDefault = true
	)
	String infoSection = "infoSection";
}

package com.logadviser;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.logadviser.data.ActivityRequirements;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AccountMode;
import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.MembershipMode;
import com.logadviser.engine.PlayerProgress;
import com.logadviser.engine.RankedActivity;
import com.logadviser.sync.CollectionLogSyncButton;
import com.logadviser.sync.CollectionLogTracker;
import com.logadviser.ui.LogAdviserPanel;
import com.logadviser.ui.TargetInfoBox;
import com.logadviser.ui.TargetTextOverlay;
import java.awt.image.BufferedImage;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.vars.AccountType;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Log Adviser",
	description = "Suggests the next collection log activity to chase, ranked by time-to-next-slot",
	tags = {"collection", "log", "clog", "adviser", "advisor"}
)
public class LogAdviserPlugin extends Plugin
{
	private static final java.util.concurrent.atomic.AtomicInteger LIVE_INSTANCES =
		new java.util.concurrent.atomic.AtomicInteger();
	private static final String CONFIG_GROUP = "logadviser";
	private static final String CFG_ACCOUNT_MODE = "accountModeOverride";
	private static final String CFG_MEMBERSHIP_MODE = "membershipModeOverride";
	private static final String CFG_IGNORE_REQ = "ignoreRequirements";
	// Calendar day (epoch days) the out-of-sync warning was last shown on, per RS profile.
	private static final String CFG_WARN_DAY = "clogWarnDay";
	// Quest completion has no dedicated event, so we re-poll on a throttled GameTick.
	private static final int PROGRESS_POLL_TICKS = 10;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ConfigManager configManager;
	@Inject private LogAdviserConfig config;
	@Inject private Gson gson;
	@Inject private ItemManager itemManager;
	@Inject private InfoBoxManager infoBoxManager;
	@Inject private OverlayManager overlayManager;
	@Inject private net.runelite.client.eventbus.EventBus eventBus;

	private StaticData staticData;
	private AdviserEngine engine;
	private CollectionLogTracker tracker;
	private LogAdviserPanel panel;
	private NavigationButton navButton;
	private TargetInfoBox currentInfoBox;
	private TargetTextOverlay textOverlay;
	// Cached account-type flag. client.getAccountType() reads a varbit and asserts
	// it's invoked on the client thread, so we never call it from startUp/EDT — only
	// from @Subscribe events (already on the client thread) and from clientThread.invokeLater.
	private volatile boolean detectedIronman = false;
	// The "collection log not synced" warning is login-only: armed when we leave the game
	// (login screen / logging in) and spent on the first sync evaluation after we are back
	// in with real data. LOGGED_IN on its own is NOT a login — RuneLite re-fires it on every
	// teleport, region cross and world hop, which is what used to spam the warning. Starts
	// armed so enabling the plugin while already logged in still warns once.
	private volatile boolean loginWarnArmed = true;
	// Union of every skill/quest referenced by activity_requirements.json — so the
	// per-tick progress poll only touches what actually gates an activity.
	private Set<Skill> reqSkills = new HashSet<>();
	private Set<Quest> reqQuests = new HashSet<>();
	// Last quest-completion snapshot, refreshed only on GameTick (a script-safe
	// point). StatChanged reuses this so it never has to run Quest.getState().
	private Set<Quest> finishedQuestsCache = new HashSet<>();
	private int progressPollTick = 0;

	@Override
	protected void startUp() throws Exception
	{
		staticData = StaticDataLoader.loadAll(gson);
		engine = new AdviserEngine(staticData, this::detectedIronman);

		reqSkills = new HashSet<>();
		reqQuests = new HashSet<>();
		for (Map.Entry<Integer, ActivityRequirements> e : staticData.getRequirementsByActivity().entrySet())
		{
			reqSkills.addAll(e.getValue().getSkillLevels().keySet());
			reqQuests.addAll(e.getValue().getQuests());
		}
		// Unmistakable build marker — if this line is absent from the client log, the
		// running client is NOT this build (stale jar / Plugin Hub copy is loaded).
		int instances = LIVE_INSTANCES.incrementAndGet();
		log.info("Log Adviser [requirement-gating build] startUp #{} (cl={}): {} requirement maps, "
				+ "skills={}, quests={}",
			instances, getClass().getClassLoader(),
			staticData.getRequirementsByActivity().size(), reqSkills, reqQuests);
		if (instances > 1)
		{
			log.warn("Log Adviser: {} live instances — a duplicate (e.g. Plugin Hub) copy "
				+ "is loaded; the panel you see may be the stale one", instances);
		}

		// Construct tracker manually — its @Inject ctor needs StaticData/AdviserEngine,
		// which aren't Guice bindings. Guice would fail with "no implementation for ..."
		// and the plugin toggle would refuse to enable.
		CollectionLogSyncButton syncButton = new CollectionLogSyncButton();
		tracker = new CollectionLogTracker(
			client,
			clientThread,
			configManager,
			staticData,
			engine,
			syncButton,
			config::hideSyncButton);
		panel = new LogAdviserPanel(
			engine,
			itemManager,
			tracker,
			staticData,
			this::onAccountModeSelected,
			this::onMembershipModeSelected,
			this::onIgnoreRequirementsSelected,
			this::onPetsOnlySelected,
			config::upcomingListSize,
			config::disableHover);

		engine.addListener(this::onRankingChanged);

		textOverlay = new TargetTextOverlay(engine);
		overlayManager.add(textOverlay);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/logadviser/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Log Adviser")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		eventBus.register(tracker);

		// Sync-status changes drive the sidebar indication + login chat warning, and the
		// infobox "data may be stale" marker. Listeners run on the client thread (tracker
		// fires them there), so the infobox rebuild needs no extra marshalling.
		tracker.addSyncListener(this::onSyncStatusChanged);
		tracker.addSyncListener(() -> onRankingChanged(engine.getRanking()));
		// "Syncing..." feedback on the panel, visible even while the collection-log redraw
		// covers the in-interface button.
		tracker.setSyncingListener(syncing -> panel.setSyncing(syncing));

		// If we're already logged in when the plugin enables (toggling at runtime), pull
		// state on the client thread — including the first read of the account-type varbit.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() ->
			{
				refreshDetectedIronman();
				tracker.load();
				tracker.evaluateSyncStatus();
				applyAccountModeFromConfig();
				applyMembershipModeFromConfig();
				applyIgnoreRequirementsFromConfig();
				refreshPlayerProgress();
				updatePlayerLabel();
				return true;
			});
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		LIVE_INSTANCES.decrementAndGet();
		if (tracker != null)
		{
			eventBus.unregister(tracker);
		}
		if (textOverlay != null)
		{
			overlayManager.remove(textOverlay);
			textOverlay = null;
		}
		if (currentInfoBox != null)
		{
			infoBoxManager.removeInfoBox(currentInfoBox);
			currentInfoBox = null;
		}
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		if (panel != null)
		{
			panel.shutdown();
		}
	}

	@Provides
	LogAdviserConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LogAdviserConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() ->
			{
				refreshDetectedIronman();
				applyAccountModeFromConfig();
				applyMembershipModeFromConfig();
				applyIgnoreRequirementsFromConfig();
				refreshPlayerProgress();
				updatePlayerLabel();
				return true;
			});
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN
			|| event.getGameState() == GameState.LOGGING_IN)
		{
			// Leaving / re-entering the game is the only thing that counts as a login, so this
			// is where the warning gets re-armed. LOGGING_IN is covered too because the client
			// can go straight LOGGING_IN -> LOADING -> LOGGED_IN without passing back through
			// the login screen. Deliberately not HOPPING: a world hop is not a login.
			loginWarnArmed = true;
			if (panel != null)
			{
				panel.setPlayerLabel(null, false);
			}
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// Account type can change in-session (group iron rank changes, "demote" actions).
		// We're on the client thread here, so reading the varbit is safe.
		refreshDetectedIronman();
		if (panel != null)
		{
			updatePlayerLabel();
		}
		// NOTE: do NOT read quest state here. VarbitChanged is posted from inside a
		// running client script; Quest.getState() runs a script and re-entering the
		// script engine throws "scripts are not reentrant". Quest polling is done on
		// GameTick (a safe, non-script point) instead.
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}
		String key = event.getKey();
		if ("displayMode".equals(key))
		{
			// Reapply the most recent ranking to add/remove infobox or clear overlay matches.
			if (engine != null)
			{
				onRankingChanged(engine.getRanking());
			}
		}
		else if ("upcomingListSize".equals(key) && engine != null && panel != null)
		{
			// Push the new size into the panel by re-rebuilding the list from the
			// most recent ranking — IntSupplier picks up the new value on read.
			panel.onRankingChanged(engine.getRanking());
		}
		else if ("disableHover".equals(key) && panel != null)
		{
			// Hide any popup that's currently showing the moment the toggle flips on.
			panel.onHoverDisabledChanged();
		}
		else if ("hideSyncButton".equals(key) && tracker != null)
		{
			// ConfigChanged arrives off the client thread; widget edits must run on it.
			clientThread.invokeLater(tracker::onHideSyncButtonChanged);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// Level-ups are immediate. getRealSkillLevel() is script-free so it's safe in
		// any event handler; quest state is taken from the cache (last GameTick poll)
		// so this never re-enters the script engine.
		if (reqSkills.contains(event.getSkill()))
		{
			refreshSkillLevels();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Quest completion has no event — poll on a throttle. setPlayerProgress() is a
		// no-op when nothing changed, so a quiet tick costs nothing past this check.
		if (reqQuests.isEmpty())
		{
			return;
		}
		if (++progressPollTick < PROGRESS_POLL_TICKS)
		{
			return;
		}
		progressPollTick = 0;
		refreshPlayerProgress();
	}

	private Map<Skill, Integer> readReqLevels()
	{
		Map<Skill, Integer> levels = new HashMap<>();
		for (Skill s : reqSkills)
		{
			levels.put(s, client.getRealSkillLevel(s));
		}
		return levels;
	}

	/** Script-free: refreshes only skill levels, reusing the cached quest snapshot.
	 *  Safe to call from any client-thread event handler (incl. StatChanged). */
	private void refreshSkillLevels()
	{
		if (engine == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		engine.setPlayerProgress(new PlayerProgress(readReqLevels(), new HashSet<>(finishedQuestsCache)));
	}

	/** Full snapshot incl. quest state. Quest.getState() runs a client script, so
	 *  this MUST only be called from a script-safe point — GameTick or a
	 *  clientThread.invokeLater callback — never directly from VarbitChanged/StatChanged. */
	private void refreshPlayerProgress()
	{
		if (engine == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		Map<Skill, Integer> levels = readReqLevels();
		Set<Quest> finished = new HashSet<>();
		for (Quest q : reqQuests)
		{
			if (q.getState(client) == QuestState.FINISHED)
			{
				finished.add(q);
			}
		}
		finishedQuestsCache = new HashSet<>(finished);
		engine.setPlayerProgress(new PlayerProgress(levels, finished));

		if (log.isDebugEnabled())
		{
			long locked = engine.getRanking().stream().filter(RankedActivity::isLocked).count();
			log.debug("Log Adviser progress: levels={}, finishedQuests={}, lockedActivities={}",
				levels, finished, locked);
		}
	}

	private void onIgnoreRequirementsSelected(boolean ignore)
	{
		configManager.setRSProfileConfiguration(CONFIG_GROUP, CFG_IGNORE_REQ, ignore);
		clientThread.invokeLater(() ->
		{
			engine.setIgnoreRequirements(ignore);
			return true;
		});
	}

	/** Toggling pets-only triggers a full engine recompute, which touches client-thread-confined
	 *  state — so marshal it onto the client thread (the panel calls this from the EDT). The filter
	 *  choice itself is transient (like the category filter) and intentionally not persisted. */
	private void onPetsOnlySelected(boolean petsOnly)
	{
		clientThread.invokeLater(() ->
		{
			engine.setPetsOnly(petsOnly);
			return true;
		});
	}

	private void applyIgnoreRequirementsFromConfig()
	{
		String saved = configManager.getRSProfileConfiguration(CONFIG_GROUP, CFG_IGNORE_REQ);
		boolean ignore = Boolean.parseBoolean(saved);
		engine.setIgnoreRequirements(ignore);
		if (panel != null)
		{
			panel.setIgnoreRequirements(ignore);
		}
	}

	/** Cheap, thread-safe read used by the engine. */
	private boolean detectedIronman()
	{
		return detectedIronman;
	}

	/** Reads the account-type varbit. MUST be called on the client thread. */
	private void refreshDetectedIronman()
	{
		AccountType type = client.getAccountType();
		boolean updated = type != null && type.isIronman();
		if (updated == detectedIronman)
		{
			return;
		}
		detectedIronman = updated;
		if (engine != null && engine.getAccountMode() == AccountMode.AUTO)
		{
			engine.refreshRates();
		}
	}

	private void onAccountModeSelected(AccountMode mode)
	{
		configManager.setRSProfileConfiguration(CONFIG_GROUP, CFG_ACCOUNT_MODE, mode.name());
		clientThread.invokeLater(() ->
		{
			engine.setAccountMode(mode);
			updatePlayerLabel();
			return true;
		});
	}

	private void applyAccountModeFromConfig()
	{
		String saved = configManager.getRSProfileConfiguration(CONFIG_GROUP, CFG_ACCOUNT_MODE);
		AccountMode mode = AccountMode.parse(saved);
		engine.setAccountMode(mode);
		if (panel != null)
		{
			panel.setAccountMode(mode);
		}
	}

	private void onMembershipModeSelected(MembershipMode mode)
	{
		configManager.setRSProfileConfiguration(CONFIG_GROUP, CFG_MEMBERSHIP_MODE, mode.name());
		clientThread.invokeLater(() ->
		{
			engine.setMembershipMode(mode);
			updatePlayerLabel();
			return true;
		});
	}

	/**
	 * Loads the saved Membership choice, seeding it on the first login for a profile from the
	 * world type (members world → P2P, free world → F2P) and persisting that concrete value —
	 * RuneLite exposes no account-membership flag, so the world is the only reliable signal.
	 * After the seed the saved value always wins. Must run on the client thread (reads getWorldType).
	 */
	private void applyMembershipModeFromConfig()
	{
		String saved = configManager.getRSProfileConfiguration(CONFIG_GROUP, CFG_MEMBERSHIP_MODE);
		MembershipMode mode = MembershipMode.parse(saved);
		if (mode == null)
		{
			boolean membersWorld = client.getWorldType().contains(WorldType.MEMBERS);
			mode = membersWorld ? MembershipMode.P2P : MembershipMode.F2P;
			configManager.setRSProfileConfiguration(CONFIG_GROUP, CFG_MEMBERSHIP_MODE, mode.name());
		}
		engine.setMembershipMode(mode);
		if (panel != null)
		{
			panel.setMembershipMode(mode);
		}
	}

	private void updatePlayerLabel()
	{
		if (panel == null)
		{
			return;
		}
		String name = client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName();
		panel.setPlayerLabel(name, detectedIronman());
	}

	/** Sync-status listener: pushes the sidebar indication and fires the login warning (at
	 *  most once a day). Runs on the client thread (tracker fires its listeners there). */
	private void onSyncStatusChanged()
	{
		boolean inSync = tracker.isInSync();
		int playerCount = tracker.playerClogCount();
		if (panel != null)
		{
			panel.setSyncStatus(inSync, playerCount);
		}
		// playerCount > 0 means the COLLECTION_COUNT varp has actually landed. Without it the
		// first post-login evaluation (varp still 0) reports inSync == true, spends the armed
		// flag, and the real out-of-sync state never gets announced.
		if (loginWarnArmed && playerCount > 0 && client.getGameState() == GameState.LOGGED_IN)
		{
			loginWarnArmed = false;
			if (!inSync && !alreadyWarnedToday())
			{
				configManager.setRSProfileConfiguration(CONFIG_GROUP, CFG_WARN_DAY,
					Integer.toString(today()));
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"Log Adviser: your collection log isn't fully synced — open it and click the Sync button.", null);
			}
		}
	}

	/** Days since the epoch, local time. Day granularity on purpose: the warning is "about
	 *  once a day", so it resets at local midnight instead of running a rolling 24h timer. */
	private static int today()
	{
		return (int) LocalDate.now().toEpochDay();
	}

	/** Read straight from config — no cached field, so there is no load-ordering concern and
	 *  nothing to reset. A missing or unparseable value means "not warned yet". */
	private boolean alreadyWarnedToday()
	{
		String saved = configManager.getRSProfileConfiguration(CONFIG_GROUP, CFG_WARN_DAY);
		if (saved == null || saved.trim().isEmpty())
		{
			return false;
		}
		try
		{
			return Integer.parseInt(saved.trim()) == today();
		}
		catch (NumberFormatException e)
		{
			return false;
		}
	}

	private void onRankingChanged(List<RankedActivity> ranking)
	{
		// Drop the old InfoBox unconditionally — it's cheaper to rebuild than to mutate.
		if (currentInfoBox != null)
		{
			infoBoxManager.removeInfoBox(currentInfoBox);
			currentInfoBox = null;
		}

		LogAdviserConfig.DisplayMode mode = config.displayMode();

		if (ranking.isEmpty())
		{
			if (textOverlay != null)
			{
				textOverlay.clearTarget();
			}
			return;
		}

		RankedActivity top = ranking.get(0);
		int displayItemId = top.getDisplayItem() != null
			? top.getDisplayItem().getItemId()
			: (top.getFastestItem() != null ? top.getFastestItem().getItemId() : -1);
		String itemName = top.getDisplayItem() != null ? top.getDisplayItem().getItemName()
			: (top.getFastestItem() != null ? top.getFastestItem().getItemName() : "");
		String hint = staticData.npcInfoFor(top.getActivity().getIndex()).getHint();

		if (mode.overlayPanel() && textOverlay != null)
		{
			textOverlay.setTarget(top, itemName, hint);
		}
		else if (textOverlay != null)
		{
			textOverlay.clearTarget();
		}

		if (mode.infoBox() && displayItemId > 0)
		{
			BufferedImage img = itemManager.getImage(displayItemId);
			currentInfoBox = new TargetInfoBox(img, this, top, itemName, hint, tracker.isInSync());
			infoBoxManager.addInfoBox(currentInfoBox);
		}
	}
}

