package com.logadviser.data;

import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;

/**
 * Resolves a free-form quest token from the requirements JSON to a RuneLite
 * {@link Quest}. Tolerant of either the enum constant name ("LUNAR_DIPLOMACY") or
 * the display name ("Lunar Diplomacy", "lunar diplomacy") — anything that
 * normalises to the same alphanumeric run matches. Unknown tokens resolve to
 * {@code null} so a typo drops that single requirement instead of hard-locking.
 */
@Slf4j
public final class QuestResolver
{
	private static final Map<String, Quest> BY_NORMALISED = new HashMap<>();

	static
	{
		for (Quest q : Quest.values())
		{
			BY_NORMALISED.putIfAbsent(normalise(q.name()), q);
			BY_NORMALISED.putIfAbsent(normalise(q.getName()), q);
		}
	}

	private QuestResolver()
	{
	}

	public static Quest resolve(String token)
	{
		if (token == null)
		{
			return null;
		}
		Quest q = BY_NORMALISED.get(normalise(token));
		if (q == null)
		{
			log.warn("Unknown quest requirement '{}' — ignoring it", token);
		}
		return q;
	}

	private static String normalise(String s)
	{
		return s == null ? "" : s.toUpperCase().replaceAll("[^A-Z0-9]", "");
	}
}

package com.logadviser.data;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;

@Value
public class StaticData
{
	List<Activity> activities;
	List<ActivityItem> activityItems;
	List<LogSlot> slots;
	Map<Integer, ActivityNpcInfo> npcInfoByActivity;
	Map<Integer, ActivityRequirements> requirementsByActivity;
	// Canonical item ids of every collection-log pet (the 68-entry OSRS "All Pets" set),
	// loaded from pets.json. Used by the "Pets Only" filter to keep only pet drops.
	Set<Integer> petItemIds;
	// Canonical item ids of every free-to-play obtainable collection-log slot, loaded from
	// f2p_slots.json (sourced from the wiki's "Collection log/Free-to-play" page). Used by the
	// "Membership" filter to hide members-only slots in F2P mode.
	Set<Integer> f2pItemIds;

	public Map<Integer, Activity> activitiesByIndex()
	{
		java.util.Map<Integer, Activity> m = new java.util.HashMap<>(activities.size() * 2);
		for (Activity a : activities)
		{
			m.put(a.getIndex(), a);
		}
		return Collections.unmodifiableMap(m);
	}

	public Map<Integer, LogSlot> slotsByItemId()
	{
		java.util.Map<Integer, LogSlot> m = new java.util.HashMap<>(slots.size() * 2);
		for (LogSlot s : slots)
		{
			m.put(s.getItemId(), s);
		}
		// Map alternate (e.g. Body-type-B) item ids onto their canonical slot so the
		// collection-log widget scrape recognises them too.
		for (Map.Entry<Integer, Integer> e : ItemAliases.canonicalByAlt().entrySet())
		{
			LogSlot canonical = m.get(e.getValue());
			if (canonical != null)
			{
				m.put(e.getKey(), canonical);
			}
		}
		return Collections.unmodifiableMap(m);
	}

	public Map<String, Integer> itemIdsByName()
	{
		java.util.Map<String, Integer> m = new java.util.HashMap<>(slots.size() * 2);
		for (LogSlot s : slots)
		{
			m.put(s.getSlotName().toLowerCase(), s.getItemId());
		}
		// Chat-message names that the canonical slotName never matches verbatim.
		m.putAll(ItemAliases.extraNames());
		return Collections.unmodifiableMap(m);
	}

	public int canonicalItemId(int itemId)
	{
		return ItemAliases.canonical(itemId);
	}

	/** True if the item id is a collection-log pet (per pets.json). */
	public boolean isPet(int itemId)
	{
		return petItemIds.contains(itemId);
	}

	/** True if the item id is a free-to-play obtainable collection-log slot (per f2p_slots.json). */
	public boolean isF2p(int itemId)
	{
		return f2pItemIds.contains(itemId);
	}

	public ActivityNpcInfo npcInfoFor(int activityIndex)
	{
		ActivityNpcInfo info = npcInfoByActivity.get(activityIndex);
		return info != null ? info : ActivityNpcInfo.empty();
	}

	public ActivityRequirements requirementsFor(int activityIndex)
	{
		ActivityRequirements req = requirementsByActivity.get(activityIndex);
		return req != null ? req : ActivityRequirements.empty();
	}
}

package com.logadviser.data;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

@Slf4j
public final class StaticDataLoader
{
	private static final String BASE = "/com/logadviser/data/";

	private StaticDataLoader()
	{
	}

	public static StaticData loadAll(Gson gson) throws IOException
	{
		List<Activity> activities = loadActivities(gson);
		List<ActivityItem> items = loadActivityItems(gson);
		List<LogSlot> slots = loadSlots(gson);
		Map<Integer, ActivityNpcInfo> npcInfo = loadNpcInfo(gson);
		Map<Integer, ActivityRequirements> requirements = loadRequirements(gson);
		Set<Integer> pets = loadPets(gson);
		Set<Integer> f2p = loadF2pSlots(gson);
		log.debug("Loaded static data: {} activities, {} items, {} slots, {} npc maps, {} requirement maps, {} pets, {} f2p slots",
			activities.size(), items.size(), slots.size(), npcInfo.size(), requirements.size(), pets.size(), f2p.size());
		return new StaticData(
			Collections.unmodifiableList(activities),
			Collections.unmodifiableList(items),
			Collections.unmodifiableList(slots),
			Collections.unmodifiableMap(npcInfo),
			Collections.unmodifiableMap(requirements),
			Collections.unmodifiableSet(pets),
			Collections.unmodifiableSet(f2p));
	}

	private static Map<Integer, ActivityRequirements> loadRequirements(Gson gson) throws IOException
	{
		try (InputStreamReader r = open("activity_requirements.json"))
		{
			JsonObject root = gson.fromJson(r, JsonObject.class);
			Map<Integer, ActivityRequirements> out = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : root.entrySet())
			{
				if (e.getKey().startsWith("_"))
				{
					continue;
				}
				int idx;
				try
				{
					idx = Integer.parseInt(e.getKey());
				}
				catch (NumberFormatException nfe)
				{
					continue;
				}
				JsonObject obj = e.getValue().getAsJsonObject();

				Map<Skill, Integer> skills = new EnumMap<>(Skill.class);
				if (obj.has("skills"))
				{
					for (Map.Entry<String, JsonElement> se : obj.getAsJsonObject("skills").entrySet())
					{
						Skill skill;
						try
						{
							skill = Skill.valueOf(se.getKey().trim().toUpperCase());
						}
						catch (IllegalArgumentException iae)
						{
							log.warn("Unknown skill requirement '{}' for activity {} — ignoring",
								se.getKey(), idx);
							continue;
						}
						skills.put(skill, se.getValue().getAsInt());
					}
				}

				List<Quest> quests = new ArrayList<>();
				List<String> rawQuests = new ArrayList<>();
				if (obj.has("quests"))
				{
					for (JsonElement qe : obj.getAsJsonArray("quests"))
					{
						String token = qe.getAsString();
						rawQuests.add(token);
						Quest q = QuestResolver.resolve(token);
						if (q != null)
						{
							quests.add(q);
						}
					}
				}

				out.put(idx, new ActivityRequirements(
					Collections.unmodifiableMap(skills),
					Collections.unmodifiableList(quests),
					Collections.unmodifiableList(rawQuests)));
			}
			return out;
		}
	}

	private static Set<Integer> loadPets(Gson gson) throws IOException
	{
		Type listType = new TypeToken<List<RawPet>>(){}.getType();
		try (InputStreamReader r = open("pets.json"))
		{
			List<RawPet> raw = gson.fromJson(r, listType);
			Set<Integer> out = new LinkedHashSet<>(raw.size() * 2);
			for (RawPet p : raw)
			{
				out.add(p.itemId);
			}
			return out;
		}
	}

	private static Set<Integer> loadF2pSlots(Gson gson) throws IOException
	{
		Type listType = new TypeToken<List<RawF2pSlot>>(){}.getType();
		try (InputStreamReader r = open("f2p_slots.json"))
		{
			List<RawF2pSlot> raw = gson.fromJson(r, listType);
			Set<Integer> out = new LinkedHashSet<>(raw.size() * 2);
			for (RawF2pSlot s : raw)
			{
				out.add(s.itemId);
			}
			return out;
		}
	}

	private static List<Activity> loadActivities(Gson gson) throws IOException
	{
		Type listType = new TypeToken<List<RawActivity>>(){}.getType();
		try (InputStreamReader r = open("activities.json"))
		{
			List<RawActivity> raw = gson.fromJson(r, listType);
			List<Activity> out = new ArrayList<>(raw.size());
			for (RawActivity a : raw)
			{
				out.add(new Activity(
					a.index,
					a.name,
					a.completionsPerHrMain,
					a.completionsPerHrIron,
					a.extraTimeFirst,
					Category.fromString(a.category)));
			}
			return out;
		}
	}

	private static List<ActivityItem> loadActivityItems(Gson gson) throws IOException
	{
		Type listType = new TypeToken<List<RawActivityItem>>(){}.getType();
		try (InputStreamReader r = open("activity_map.json"))
		{
			List<RawActivityItem> raw = gson.fromJson(r, listType);
			List<ActivityItem> out = new ArrayList<>(raw.size());
			for (RawActivityItem ri : raw)
			{
				out.add(new ActivityItem(
					ri.activityIndex,
					ri.itemId,
					ri.itemName,
					ri.slotDifficulty,
					ri.requiresPrevious,
					ri.exact,
					ri.independent,
					ri.dropRateAttempts));
			}
			return out;
		}
	}

	private static List<LogSlot> loadSlots(Gson gson) throws IOException
	{
		Type listType = new TypeToken<List<RawSlot>>(){}.getType();
		try (InputStreamReader r = open("slots.json"))
		{
			List<RawSlot> raw = gson.fromJson(r, listType);
			List<LogSlot> out = new ArrayList<>(raw.size());
			for (RawSlot rs : raw)
			{
				out.add(new LogSlot(rs.itemId, rs.slotName, rs.activityCount));
			}
			return out;
		}
	}

	private static Map<Integer, ActivityNpcInfo> loadNpcInfo(Gson gson) throws IOException
	{
		try (InputStreamReader r = open("activity_npcs.json"))
		{
			JsonObject root = gson.fromJson(r, JsonObject.class);
			Map<Integer, ActivityNpcInfo> out = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : root.entrySet())
			{
				if (e.getKey().startsWith("_"))
				{
					continue;
				}
				int idx;
				try
				{
					idx = Integer.parseInt(e.getKey());
				}
				catch (NumberFormatException nfe)
				{
					continue;
				}
				JsonObject obj = e.getValue().getAsJsonObject();
				List<Integer> ids = new ArrayList<>();
				if (obj.has("npcIds"))
				{
					obj.getAsJsonArray("npcIds").forEach(je -> ids.add(je.getAsInt()));
				}
				String hint = obj.has("hint") ? obj.get("hint").getAsString() : "";
				out.put(idx, new ActivityNpcInfo(Collections.unmodifiableList(ids), hint));
			}
			return out;
		}
	}

	private static InputStreamReader open(String name) throws IOException
	{
		InputStream in = StaticDataLoader.class.getResourceAsStream(BASE + name);
		if (in == null)
		{
			throw new IOException("Missing resource: " + BASE + name);
		}
		return new InputStreamReader(in, StandardCharsets.UTF_8);
	}

	private static final class RawActivity
	{
		int index;
		String name;
		double completionsPerHrMain;
		double completionsPerHrIron;
		double extraTimeFirst;
		String category;
	}

	private static final class RawActivityItem
	{
		int activityIndex;
		int itemId;
		String itemName;
		int slotDifficulty;
		boolean requiresPrevious;
		boolean exact;
		boolean independent;
		double dropRateAttempts;
	}

	private static final class RawSlot
	{
		int itemId;
		String slotName;
		int activityCount;
	}

	private static final class RawPet
	{
		int itemId;
		String name; // documentation only; the engine matches on itemId
	}

	private static final class RawF2pSlot
	{
		int itemId;
		String name; // documentation only; the engine matches on itemId
	}
}

