	public List<RankedActivity> getRanking()
	{
		List<RankedActivity> out = new ArrayList<>();
		for (Activity a : data.getActivities())
		{
			if (!matchesShowFilter(a))
			{
				continue;
			}
			if (activeSkipSet().contains(a.getIndex()))
			{
				continue;
			}
			Double t = cachedTime.get(a.getIndex());
			if (t == null || Double.isInfinite(t) || Double.isNaN(t))
			{
				continue;
			}
			int[] slots = cachedSlotCounts.getOrDefault(a.getIndex(), new int[]{0, 0});
			String missing = unmetRequirementLabel(a.getIndex());
			out.add(new RankedActivity(
				a,
				t,
				cachedDisplay.get(a.getIndex()),
				cachedFastest.get(a.getIndex()),
				slots[0],
				slots[1],
				missing != null,
				missing));
		}
		// Unlocked first (by time-to-slot), then locked activities demoted to the
		// bottom — themselves still ordered by time so the closest unlock floats up.
		out.sort((x, y) ->
		{
			if (x.isLocked() != y.isLocked())
			{
				return x.isLocked() ? 1 : -1;
			}
			return Double.compare(x.getTimeToNextSlotHours(), y.getTimeToNextSlotHours());
		});
		return petsOnly ? dedupeByPet(out) : out;
	}

	/**
	 * Collapses a pets-mode ranking to one row per pet. The list must already be sorted
	 * (unlocked-first, then by time), so keeping the first occurrence of each display-pet id yields
	 * the fastest unlocked source — or, when every source is locked, the fastest locked one (which
	 * stays in the demoted locked block). Rows without a display item are left untouched.
	 */
	private List<RankedActivity> dedupeByPet(List<RankedActivity> ranked)
	{
		List<RankedActivity> out = new ArrayList<>(ranked.size());
		Set<Integer> seenPets = new HashSet<>();
		for (RankedActivity r : ranked)
		{
			ActivityItem display = r.getDisplayItem();
			if (display != null && !seenPets.add(display.getItemId()))
			{
				continue;
			}
			out.add(r);
		}
		return out;
	}

	/** The skipped activities, ranked like {@link #getRanking()} but containing
	 *  only what the player has skipped. Ignores the category filter so a
	 *  filtered-out skip is still visible (and recoverable) in the skip list. */
	public List<RankedActivity> getSkippedRanking()
	{
		List<RankedActivity> out = new ArrayList<>();
		for (Activity a : data.getActivities())
		{
			if (!activeSkipSet().contains(a.getIndex()))
			{
				continue;
			}
			Double t = cachedTime.get(a.getIndex());
			if (t == null || Double.isInfinite(t) || Double.isNaN(t))
			{
				continue;
			}
			int[] slots = cachedSlotCounts.getOrDefault(a.getIndex(), new int[]{0, 0});
			String missing = unmetRequirementLabel(a.getIndex());
			out.add(new RankedActivity(
				a,
				t,
				cachedDisplay.get(a.getIndex()),
				cachedFastest.get(a.getIndex()),
				slots[0],
				slots[1],
				missing != null,
				missing));
		}
		out.sort((x, y) ->
		{
			if (x.isLocked() != y.isLocked())
			{
				return x.isLocked() ? 1 : -1;
			}
			return Double.compare(x.getTimeToNextSlotHours(), y.getTimeToNextSlotHours());
		});
		return petsOnly ? dedupeByPet(out) : out;
	}

