	private void recomputeAll()
	{
		cachedTime.clear();
		cachedFastest.clear();
		cachedDisplay.clear();
		cachedSlotCounts.clear();
		for (Integer idx : itemsByActivity.keySet())
		{
			recomputeActivity(idx);
		}
	}

	private void recomputeActivity(int activityIndex)
	{
		Activity activity = activitiesByIndex.get(activityIndex);
		List<ActivityItem> items = itemsByActivity.get(activityIndex);
		if (activity == null || items == null || items.isEmpty())
		{
			cachedTime.put(activityIndex, Double.POSITIVE_INFINITY);
			return;
		}
		items = visibleItems(items);
		if (items.isEmpty())
		{
			// Every item this activity drops is iron-auto-completed: treat the
			// activity as having nothing to chase, mirroring an absent activity_map row.
			cachedTime.put(activityIndex, Double.POSITIVE_INFINITY);
			cachedSlotCounts.put(activityIndex, new int[]{0, 0});
			return;
		}
		double cph = isUsingIronRates() ? activity.getCompletionsPerHrIron() : activity.getCompletionsPerHrMain();
		if (cph <= 0.0)
		{
			cachedTime.put(activityIndex, Double.POSITIVE_INFINITY);
			cachedSlotCounts.put(activityIndex, slotCounts(items));
			return;
		}

		// Active flag mirrors the xlsx: !Completed AND (!RequiresPrevious OR prevRow.Completed)
		boolean[] active = new boolean[items.size()];
		boolean prevCompleted = false;
		for (int i = 0; i < items.size(); i++)
		{
			ActivityItem it = items.get(i);
			boolean done = obtained.contains(it.getItemId());
			boolean requiresPrev = it.isRequiresPrevious();
			if (done)
			{
				active[i] = false;
			}
			else if (!requiresPrev)
			{
				active[i] = true;
			}
			else
			{
				active[i] = prevCompleted;
			}
			prevCompleted = done;
		}

		// Pets-only: deactivate every non-pet drop, so the bucket math below times this activity
		// against just its remaining pet(s). One pet → its own rate; several at once (Dagannoth
		// Kings) → they share the "Neither" harmonic bucket, giving the combined shared rate.
		// If no pet is left active, no bucket gets a finite time and getRanking drops the activity.
		if (petsOnly)
		{
			for (int i = 0; i < items.size(); i++)
			{
				if (active[i] && !data.isPet(items.get(i).getItemId()))
				{
					active[i] = false;
				}
			}
		}

		// Bucket active items by (exact, independent). For each bucket also remember the
		// smallest-attempts item — that's the single slot the bucket's time is driven by
		// (for "Neither", the slot most likely to drop first), used to pick the display item.
		double sumInverseNeither = 0.0;
		double minK_neither = Double.POSITIVE_INFINITY;
		double minK_indOnly = Double.POSITIVE_INFINITY;
		double minK_exactOnly = Double.POSITIVE_INFINITY;
		double minK_ei = Double.POSITIVE_INFINITY;
		ActivityItem neitherMin = null;
		ActivityItem indMin = null;
		ActivityItem exactMin = null;
		ActivityItem eiMin = null;

		ActivityItem fastest = null;
		double fastestK = Double.POSITIVE_INFINITY;

		for (int i = 0; i < items.size(); i++)
		{
			if (!active[i])
			{
				continue;
			}
			ActivityItem it = items.get(i);
			double k = it.getDropRateAttempts();
			if (k <= 0.0)
			{
				continue;
			}
			boolean ex = it.isExact();
			boolean in = it.isIndependent();
			if (!ex && !in)
			{
				sumInverseNeither += 1.0 / k;
				if (k < minK_neither)
				{
					minK_neither = k;
					neitherMin = it;
				}
			}
			else if (!ex && in)
			{
				if (k < minK_indOnly)
				{
					minK_indOnly = k;
					indMin = it;
				}
			}
			else if (ex && !in)
			{
				if (k < minK_exactOnly)
				{
					minK_exactOnly = k;
					exactMin = it;
				}
			}
			else
			{
				if (k < minK_ei)
				{
					minK_ei = k;
					eiMin = it;
				}
			}

			if (k < fastestK)
			{
				fastestK = k;
				fastest = it;
			}
		}

		double timeNeither = sumInverseNeither > 0.0
			? (1.0 / sumInverseNeither) / cph + activity.getExtraTimeFirst()
			: Double.POSITIVE_INFINITY;
		double timeInd = Double.isFinite(minK_indOnly)
			? minK_indOnly / cph + activity.getExtraTimeFirst()
			: Double.POSITIVE_INFINITY;
		double timeExact = Double.isFinite(minK_exactOnly)
			? minK_exactOnly / cph + activity.getExtraTimeFirst()
			: Double.POSITIVE_INFINITY;
		double timeEI = Double.isFinite(minK_ei)
			? minK_ei / cph + activity.getExtraTimeFirst()
			: Double.POSITIVE_INFINITY;

		double best = Math.min(Math.min(timeNeither, timeInd), Math.min(timeExact, timeEI));
		cachedTime.put(activityIndex, best);

		// The display item is the slot that produced `best`: the min-attempts item of the
		// winning bucket (ties broken toward the smaller-attempts item). `best` is a min of the
		// exact bucket times, so `== best` reliably identifies the winner.
		ActivityItem display = null;
		double displayK = Double.POSITIVE_INFINITY;
		if (neitherMin != null && timeNeither == best && minK_neither < displayK)
		{
			display = neitherMin;
			displayK = minK_neither;
		}
		if (indMin != null && timeInd == best && minK_indOnly < displayK)
		{
			display = indMin;
			displayK = minK_indOnly;
		}
		if (exactMin != null && timeExact == best && minK_exactOnly < displayK)
		{
			display = exactMin;
			displayK = minK_exactOnly;
		}
		if (eiMin != null && timeEI == best && minK_ei < displayK)
		{
			display = eiMin;
			displayK = minK_ei;
		}

		if (fastest != null)
		{
			cachedFastest.put(activityIndex, fastest);
		}
		// Fall back to the global fastest only if no bucket won (e.g. `best` non-finite); when
		// the activity is rankable `display` is always set.
		cachedDisplay.put(activityIndex, display != null ? display : fastest);
		cachedSlotCounts.put(activityIndex, slotCounts(items));
	}

	/**
	 * The items an activity should be evaluated against for the current account type and
	 * membership filter. On iron rates this drops {@link #IRON_AUTO_COMPLETED} slots; in F2P
	 * mode it keeps only free-to-play obtainable slots ({@link StaticData#isF2p}). Dropped slots
	 * neither show up in the ranking nor count toward the activity's slot total — an activity
	 * left with no items is treated as having nothing to chase (see {@link #recomputeActivity}).
	 * Recomputed whenever the iron/main signal or the membership mode changes.
	 */
	private List<ActivityItem> visibleItems(List<ActivityItem> items)
	{
		boolean iron = isUsingIronRates();
		boolean f2pOnly = membershipMode == MembershipMode.F2P;
		if (!iron && !f2pOnly)
		{
			return items;
		}
		List<ActivityItem> out = new ArrayList<>(items.size());
		for (ActivityItem it : items)
		{
			if (iron && IRON_AUTO_COMPLETED.contains(it.getItemId()))
			{
				continue;
			}
			if (f2pOnly && !data.isF2p(it.getItemId()))
			{
				continue;
			}
			out.add(it);
		}
		return out;
	}

	private int[] slotCounts(List<ActivityItem> items)
	{
		Set<Integer> uniq = new HashSet<>();
		Set<Integer> uniqDone = new HashSet<>();
		for (ActivityItem it : items)
		{
			uniq.add(it.getItemId());
			if (obtained.contains(it.getItemId()))
			{
				uniqDone.add(it.getItemId());
			}
		}
		int total = uniq.size();
		int left = total - uniqDone.size();
		return new int[]{left, total};
	}

	private void fire()
	{
		List<RankedActivity> snapshot = getRanking();
		for (Consumer<List<RankedActivity>> l : listeners)
		{
			try
			{
				l.accept(snapshot);
			}
			catch (RuntimeException ex)
			{
				log.warn("Listener threw", ex);
			}
		}
	}
}

package com.logadviser.engine;

/**
 * The "Membership" filter, a sibling of {@link AccountMode}. Unlike account mode there is no
 * live AUTO state: on the first login for a profile the plugin seeds the value from the world
 * type ({@code WorldType.MEMBERS}) and persists a concrete F2P/P2P choice, after which the saved
 * value always wins. {@code P2P} applies no filter (a member can collect everything); {@code F2P}
 * keeps only the free-to-play obtainable slots (see f2p_slots.json).
 */
public enum MembershipMode
{
	F2P,
	P2P;

	/**
	 * Parses the saved override string. Returns {@code null} when nothing is saved (or the value
	 * is unrecognised) so the caller knows to seed the default from the player's world type.
	 */
	public static MembershipMode parse(String s)
	{
		if (s == null)
		{
			return null;
		}
		try
		{
			return valueOf(s.toUpperCase());
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}
}

package com.logadviser.engine;

import java.util.Collections;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import lombok.Value;

/**
 * Immutable snapshot of the bits of player state that gate activities: real
 * (un-boosted) skill levels and the set of finished quests. Built on the client
 * thread by the plugin and pushed into {@link AdviserEngine}. {@link #EMPTY} means
 * "nothing known yet" — everything is treated as locked until the first refresh.
 */
@Value
public class PlayerProgress
{
	Map<Skill, Integer> realLevels;
	Set<Quest> finishedQuests;

	public static final PlayerProgress EMPTY =
		new PlayerProgress(Collections.emptyMap(), Collections.emptySet());

	public int level(Skill skill)
	{
		Integer l = realLevels.get(skill);
		return l == null ? 0 : l;
	}

	public boolean isFinished(Quest quest)
	{
		return finishedQuests.contains(quest);
	}
}

package com.logadviser.engine;

import com.logadviser.data.Activity;
import com.logadviser.data.ActivityItem;
import lombok.Value;

@Value
public class RankedActivity
{
	Activity activity;
	double timeToNextSlotHours;
	// The slot the time estimate is for — the next slot you're most likely to obtain (the one
	// driving timeToNextSlotHours). The UI headlines this so the icon/name always match the time.
	ActivityItem displayItem;
	ActivityItem fastestItem;
	int slotsLeft;
	int slotsTotal;
	boolean locked;
	String requirementLabel;

	public double percentComplete()
	{
		return slotsTotal == 0 ? 0.0 : 1.0 - (double) slotsLeft / slotsTotal;
	}
}

