package com.logadviser.sync;

import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.SpriteID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;

/**
 * Builds a native-looking "Sync" button on the collection log header, styled to match the
 * in-game Search button (and the Temple-OSRS button it's modelled on). It is a 9-slice
 * made of nine GRAPHIC children (centre fill + four corners + four edges) plus a refresh
 * icon, all overlaid by a single TEXT child that carries the menu action and click/hover
 * listeners. Hovering swaps the nine slice sprites to their highlighted variants, exactly
 * like the real header buttons.
 *
 * <p>Every child uses {@link WidgetPositionMode#ABSOLUTE_RIGHT}: in that mode {@code x} is
 * the distance from the parent's RIGHT edge to the child's RIGHT edge, so a larger {@code x}
 * sits further LEFT. All the layout maths below is in that "distance from the right" space.
 * The button is anchored just left of the live Search button so it aligns at any scale.
 *
 * <p>All methods mutate game widgets and so MUST run on the client thread (collection-log
 * setup script + op listener).
 */
public final class CollectionLogSyncButton
{
	private static final String SYNC_ACTION = "Sync collection log";
	private static final String LABEL_IDLE = "Log Sync";
	private static final String LABEL_BUSY = "Syncing...";

	private static final int FONT_COLOUR_IDLE = 0xd6d6d6;
	private static final int FONT_COLOUR_HOVER = 0xffffff;

	private static final int BUTTON_WIDTH = 78; // snug fit for "Log Sync" beside the icon
	private static final int FALLBACK_RIGHT = 33; // distance from right edge if the Search button isn't loaded
	private static final int GAP_FROM_SEARCH = 4; // gap between our button and the Search button
	private static final int CORNER = 9;
	private static final int ICON_SIZE = 13;
	private static final int PAD_LEFT = 4;   // border -> icon
	private static final int ICON_GAP = 4;   // icon -> text
	private static final int PAD_RIGHT = 6;  // text -> border

	// 9-slice sprite sets: index 0 = centre fill, 1-4 = corners (TL, TR, BL, BR),
	// 5-8 = edges (left, top, right, bottom). Idle reuses the world-map metal button
	// sprites; hover uses the equipment button's highlighted variants — the same families
	// the genuine collection log header buttons are drawn from.
	private static final int[] SLICE_IDLE = {
		SpriteID.DIALOG_BACKGROUND,
		SpriteID.WORLD_MAP_BUTTON_METAL_CORNER_TOP_LEFT,
		SpriteID.WORLD_MAP_BUTTON_METAL_CORNER_TOP_RIGHT,
		SpriteID.WORLD_MAP_BUTTON_METAL_CORNER_BOTTOM_LEFT,
		SpriteID.WORLD_MAP_BUTTON_METAL_CORNER_BOTTOM_RIGHT,
		SpriteID.WORLD_MAP_BUTTON_EDGE_LEFT,
		SpriteID.WORLD_MAP_BUTTON_EDGE_TOP,
		SpriteID.WORLD_MAP_BUTTON_EDGE_RIGHT,
		SpriteID.WORLD_MAP_BUTTON_EDGE_BOTTOM,
	};

	private static final int[] SLICE_HOVER = {
		SpriteID.RESIZEABLE_MODE_SIDE_PANEL_BACKGROUND,
		SpriteID.EQUIPMENT_BUTTON_METAL_CORNER_TOP_LEFT_HOVERED,
		SpriteID.EQUIPMENT_BUTTON_METAL_CORNER_TOP_RIGHT_HOVERED,
		SpriteID.EQUIPMENT_BUTTON_METAL_CORNER_BOTTOM_LEFT_HOVERED,
		SpriteID.EQUIPMENT_BUTTON_METAL_CORNER_BOTTOM_RIGHT_HOVERED,
		SpriteID.EQUIPMENT_BUTTON_EDGE_LEFT_HOVERED,
		SpriteID.EQUIPMENT_BUTTON_EDGE_TOP_HOVERED,
		SpriteID.EQUIPMENT_BUTTON_EDGE_RIGHT_HOVERED,
		SpriteID.EQUIPMENT_BUTTON_EDGE_BOTTOM_HOVERED,
	};

	// The nine slice widgets (for the hover swap), the refresh icon, and the text overlay.
	private final Widget[] slices = new Widget[SLICE_IDLE.length];
	private Widget icon;
	private Widget text;
	private boolean attached = false;
	// Logical "sync in flight" state, kept independent of the widget lifecycle so it
	// survives an interface rebuild (which wipes and re-creates the button mid-sync).
	private boolean busy = false;

	/** Builds the button on the collection log header if it isn't already there. */
	public void attach(Client client, Runnable onClick)
	{
		Widget parent = client.getWidget(InterfaceID.Collection.UNIVERSE);
		if (parent == null)
		{
			return;
		}
		// If the button already exists (a redraw that didn't wipe the container's children),
		// re-adopt our overlay so the busy label keeps updating instead of going stale — then
		// re-apply the current sync state so it shows "Syncing..." again.
		Widget[] dyn = parent.getDynamicChildren();
		int existing = findExistingText(dyn);
		if (existing >= 0)
		{
			adopt(dyn, existing);
			attached = true;
			applyBusyState();
			return;
		}
		Widget searchButton = client.getWidget(InterfaceID.Collection.SEARCH_TOGGLE);

		final int w = BUTTON_WIDTH;
		final int h = searchButton != null ? searchButton.getOriginalHeight() : 20;
		// Right edge of our button = just left of the Search button (both ABSOLUTE_RIGHT).
		final int x = searchButton != null
			? searchButton.getOriginalX() + searchButton.getOriginalWidth() + GAP_FROM_SEARCH
			: FALLBACK_RIGHT;
		final int y = searchButton != null ? searchButton.getOriginalY() : 5;
		final int yMode = searchButton != null
			? searchButton.getYPositionMode() : WidgetPositionMode.ABSOLUTE_TOP;
		final int sideH = Math.max(1, h - 2 * CORNER);
		final int edgeW = Math.max(1, w - 2 * CORNER);

		// [0] centre fill — spans the whole button, tiled so the texture doesn't stretch.
		slices[0] = slice(parent, SLICE_IDLE[0], x, y, w, h, yMode, true);
		// Corners. Remember: x = right edge, x + (w - CORNER) = left edge.
		slices[1] = slice(parent, SLICE_IDLE[1], x + (w - CORNER), y, CORNER, CORNER, yMode, false); // top-left
		slices[2] = slice(parent, SLICE_IDLE[2], x, y, CORNER, CORNER, yMode, false);                // top-right
		slices[3] = slice(parent, SLICE_IDLE[3], x + (w - CORNER), y + h - CORNER, CORNER, CORNER, yMode, false); // bottom-left
		slices[4] = slice(parent, SLICE_IDLE[4], x, y + h - CORNER, CORNER, CORNER, yMode, false);    // bottom-right
		// Edges between the corners.
		slices[5] = slice(parent, SLICE_IDLE[5], x + (w - CORNER), y + CORNER, CORNER, sideH, yMode, false); // left
		slices[6] = slice(parent, SLICE_IDLE[6], x + CORNER, y, edgeW, CORNER, yMode, false);               // top
		slices[7] = slice(parent, SLICE_IDLE[7], x, y + CORNER, CORNER, sideH, yMode, false);               // right
		slices[8] = slice(parent, SLICE_IDLE[8], x + CORNER, y + h - CORNER, edgeW, CORNER, yMode, false);  // bottom

		// Refresh-arrows icon on the LEFT of the label (decorative, not swapped on hover).
		icon = parent.createChild(-1, WidgetType.GRAPHIC);
		icon.setSpriteId(SpriteID.UNKNOWN_WHITE_REFRESH_ARROWS);
		icon.setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT);
		icon.setYPositionMode(yMode);
		icon.setOriginalWidth(ICON_SIZE);
		icon.setOriginalHeight(ICON_SIZE);
		icon.setOriginalX(x + w - PAD_LEFT - ICON_SIZE); // left edge sits PAD_LEFT in from the button's left
		icon.setOriginalY(y + (h - ICON_SIZE) / 2);
		icon.revalidate();

		for (Widget s : slices)
		{
			if (s != null)
			{
				s.revalidate();
			}
		}

		// Clickable text overlay — occupies the space to the right of the icon, with
		// PAD_RIGHT of breathing room before the border. Carries all the listeners.
		final int textWidth = Math.max(1, w - PAD_LEFT - ICON_SIZE - ICON_GAP - PAD_RIGHT);
		Widget label = parent.createChild(-1, WidgetType.TEXT);
		label.setText(LABEL_IDLE);
		label.setTextColor(FONT_COLOUR_IDLE);
		label.setFontId(FontID.PLAIN_11);
		label.setTextShadowed(true);
		label.setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT);
		label.setYPositionMode(yMode);
		label.setXTextAlignment(WidgetTextAlignment.CENTER);
		label.setYTextAlignment(WidgetTextAlignment.CENTER);
		label.setOriginalWidth(textWidth);
		label.setOriginalHeight(h);
		label.setOriginalX(x + PAD_RIGHT);
		label.setOriginalY(y);
		label.setHasListener(true);
		label.setAction(0, SYNC_ACTION);
		label.setOnOpListener((JavaScriptCallback) ev -> onClick.run());
		label.setOnMouseOverListener((JavaScriptCallback) ev -> setHover(true));
		label.setOnMouseLeaveListener((JavaScriptCallback) ev -> setHover(false));
		label.revalidate();

		this.text = label;
		this.attached = true;
		// Re-apply the current sync state so a rebuild mid-sync still shows "Syncing...".
		applyBusyState();
		parent.revalidate();
	}

	/** Flips the button into/out of its "Syncing..." state. Safe to call before attach —
	 *  the state is re-applied when the button is (re)built. */
	public void setBusy(boolean busy)
	{
		this.busy = busy;
		applyBusyState();
	}

	/** Takes a live button off the collection log header (the "hide button" option was switched
	 *  on while the log is open). Widgets can't be removed one by one without wiping other
	 *  plugins' children too, so ours are hidden and the overlay loses its action and listeners —
	 *  {@link #findExistingText} no longer matches it and a later {@link #attach} builds fresh.
	 *  The inert leftovers go away with the next interface rebuild. */
	public void detach()
	{
		for (Widget s : slices)
		{
			hide(s);
		}
		hide(icon);
		if (text != null)
		{
			text.setAction(0, null);
			text.setHasListener(false);
			text.setOnOpListener((Object[]) null);
			text.setOnMouseOverListener((Object[]) null);
			text.setOnMouseLeaveListener((Object[]) null);
			hide(text);
		}
		reset();
	}

	private static void hide(Widget w)
	{
		if (w != null)
		{
			w.setHidden(true);
			w.revalidate();
		}
	}

	/** Forgets the button — call when the interface closes/rebuilds (its children are wiped).
	 *  The {@link #busy} flag is intentionally kept so an in-flight sync re-renders correctly. */
	public void reset()
	{
		java.util.Arrays.fill(slices, null);
		icon = null;
		text = null;
		attached = false;
	}

	/** While syncing, hide the icon and centre the longer "Syncing..." label across the
	 *  whole button; otherwise show the icon with the "Sync" label beside it. */
	private void applyBusyState()
	{
		if (text == null)
		{
			return;
		}
		int idleWidth = Math.max(1, BUTTON_WIDTH - PAD_LEFT - ICON_SIZE - ICON_GAP - PAD_RIGHT);
		int busyWidth = Math.max(1, BUTTON_WIDTH - PAD_LEFT - PAD_RIGHT);
		text.setText(busy ? LABEL_BUSY : LABEL_IDLE);
		text.setOriginalWidth(busy ? busyWidth : idleWidth);
		text.revalidate();
		if (icon != null)
		{
			icon.setHidden(busy);
			icon.revalidate();
		}
	}

	private void setHover(boolean hover)
	{
		int[] set = hover ? SLICE_HOVER : SLICE_IDLE;
		for (int i = 0; i < slices.length; i++)
		{
			if (slices[i] != null)
			{
				slices[i].setSpriteId(set[i]);
			}
		}
		if (text != null)
		{
			text.setTextColor(hover ? FONT_COLOUR_HOVER : FONT_COLOUR_IDLE);
		}
	}

	private static Widget slice(Widget parent, int spriteId, int x, int y, int w, int h, int yMode, boolean tile)
	{
		Widget s = parent.createChild(-1, WidgetType.GRAPHIC);
		s.setSpriteId(spriteId);
		s.setSpriteTiling(tile);
		s.setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT);
		s.setYPositionMode(yMode);
		s.setOriginalWidth(w);
		s.setOriginalHeight(h);
		s.setOriginalX(x);
		s.setOriginalY(y);
		return s;
	}

	/** Re-adopts a button that survived a redraw. {@link #attach} creates the nine slices, the
	 *  icon and the overlay back to back on the client thread, so they sit directly before the
	 *  overlay in the child array; they are only picked up if that still checks out, so the hover
	 *  swap and {@link #detach} reach the whole button rather than just its label. */
	private void adopt(Widget[] dyn, int textIndex)
	{
		text = dyn[textIndex];
		int iconIndex = textIndex - 1;
		int firstSlice = iconIndex - slices.length;
		if (firstSlice < 0 || !isGraphic(dyn[iconIndex], SpriteID.UNKNOWN_WHITE_REFRESH_ARROWS))
		{
			return;
		}
		for (int i = 0; i < slices.length; i++)
		{
			Widget s = dyn[firstSlice + i];
			if (!isGraphic(s, SLICE_IDLE[i]) && !isGraphic(s, SLICE_HOVER[i]))
			{
				return;
			}
		}
		icon = dyn[iconIndex];
		System.arraycopy(dyn, firstSlice, slices, 0, slices.length);
	}

	private static boolean isGraphic(Widget w, int spriteId)
	{
		return w != null && w.getType() == WidgetType.GRAPHIC && w.getSpriteId() == spriteId;
	}

	/** Index of our clickable text overlay among the container's dynamic children (identified
	 *  by its menu action), or -1 if the button isn't present. */
	private static int findExistingText(Widget[] dyn)
	{
		if (dyn == null)
		{
			return -1;
		}
		for (int i = 0; i < dyn.length; i++)
		{
			Widget w = dyn[i];
			if (w == null)
			{
				continue;
			}
			String[] actions = w.getActions();
			if (actions == null)
			{
				continue;
			}
			for (String a : actions)
			{
				if (SYNC_ACTION.equals(a))
				{
					return i;
				}
			}
		}
		return -1;
	}
}

package com.logadviser.sync;

import com.logadviser.data.LogSlot;
import com.logadviser.data.StaticData;
import com.logadviser.engine.AdviserEngine;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.BooleanSupplier;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * The collection log "sync brain". Three things feed the obtained set:
 *   1) ChatMessage "New item added to your collection log" — live drops.
 *   2) A one-click full sync: a {@link CollectionLogSyncButton} on the collection log
 *      interface presses the game's own Search and runs the enumerate script (2240),
 *      which fires per-item callback script 4100 for every obtained item — we harvest
 *      those and merge them in. This replaces the old open-every-page scrape.
 *
 * It also answers "is the plugin's data behind the player's real collection log?" by
 * comparing the player's true {@link VarPlayerID#COLLECTION_COUNT} against a persisted
 * baseline captured at the last point our data was known-complete. Out-of-sync drives a
 * login warning and the sidebar indication.
 *
 * <p>All mutating work runs on the client thread; the panel reads the {@code volatile}
 * {@link #inSync}/{@link #playerCount} fields cross-thread.
 */
@Slf4j
@Singleton
public class CollectionLogTracker
{
	private static final String CONFIG_GROUP = "logadviser";
	private static final String CONFIG_KEY = "obtained";
	private static final String CONFIG_KEY_SKIPPED = "skipped";
	private static final String CONFIG_KEY_SKIPPED_PETS = "skippedPets";
	private static final int COLLECTION_LOG_DRAW_SCRIPT_ID = 2731;
	private static final String CONFIG_KEY_BASELINE = "clogBaseline";
	private static final String NEW_ITEM_PREFIX = "New item added to your collection log:";

	// Fires once when the collection log interface is built — re-attach the button here.
	private static final int SCRIPT_COLLECTION_SETUP = 7797;
	// Per-item callback the enumerate script fires for every OBTAINED slot.
	private static final int SCRIPT_COLLECTION_ITEM = 4100;
	// The cs2 proc that walks the whole log and re-fires 4100 for all obtained items.
	private static final int SCRIPT_ENUMERATE_LOG = 2240;
	// Large logs keep firing 4100 for a few ticks; settle before consuming the harvest.
	private static final int SYNC_SETTLE_TICKS = 3;

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final StaticData staticData;
	private final AdviserEngine engine;
	private final CollectionLogSyncButton syncButton;
	// Read live from config, so the option takes effect on the next attach without a restart.
	private final BooleanSupplier hideSyncButton;

	private final Map<String, Integer> itemIdsByName;

	// Full-sync harvest state (client thread only).
	private final Set<Integer> harvest = new HashSet<>();
	private Integer gameTickToSync = null;
	// True only between a Sync-button click and the harvest being consumed — gates the
	// "Syncing..." button label and the baseline re-pin (passive 4100s from just browsing
	// the log still get merged, but must not claim a full sync).
	private boolean fullSyncRequested = false;

	// Sync-status state (client thread only, except the volatiles read by the panel).
	private int baseline = -1;            // player COLLECTION_COUNT at last known-complete; -1 = none stored
	private boolean migrationDone = false; // one-shot per login: seed/keep baseline once the varp is known
	private int obtainedCountAtLogin = 0;  // captured at load() so live drops can't flip the migration call
	private volatile boolean inSync = true;
	private volatile int playerCount = 0;

	private final List<Runnable> syncListeners = new CopyOnWriteArrayList<>();
	// Notified true when a full sync starts and false when it finishes, so the panel can
	// show "Syncing..." somewhere the collection-log redraw can't cover (unlike the button).
	private java.util.function.Consumer<Boolean> syncingListener;

	@Inject
	public CollectionLogTracker(
		Client client,
		ClientThread clientThread,
		ConfigManager configManager,
		StaticData staticData,
		AdviserEngine engine,
		CollectionLogSyncButton syncButton,
		BooleanSupplier hideSyncButton)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.staticData = staticData;
		this.engine = engine;
		this.syncButton = syncButton;
		this.hideSyncButton = hideSyncButton;
		this.itemIdsByName = staticData.itemIdsByName();
	}

	public void load()
	{
		Set<Integer> ids = parseCsv(configManager.getRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY));
		Set<Integer> skips = parseCsv(configManager.getRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY_SKIPPED));
		Set<Integer> petSkips = parseCsv(configManager.getRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY_SKIPPED_PETS));
		engine.replaceObtained(ids);
		engine.replaceSkipped(skips);
		engine.replacePetsSkipped(petSkips);

		String savedBaseline = configManager.getRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY_BASELINE);
		if (savedBaseline != null && !savedBaseline.isEmpty())
		{
			try
			{
				baseline = Integer.parseInt(savedBaseline.trim());
				migrationDone = true;
			}
			catch (NumberFormatException ex)
			{
				baseline = -1;
				migrationDone = false;
			}
		}
		else
		{
			baseline = -1;
			migrationDone = false;
		}
		// Snapshot the recorded count NOW, before any live drops this session, so the
		// migration decision (existing user vs. brand new) can't be skewed later.
		obtainedCountAtLogin = engine.collectedSlotCount();
	}

	public void persist()
	{
		configManager.setRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY, toCsv(engine.obtainedItems()));
		persistSkipped();
	}

	/** Persists both skip lists (normal + pet-mode) — each mode owns its own config key, so the
	 *  one not currently active is preserved rather than clobbered. */
	public void persistSkipped()
	{
		configManager.setRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY_SKIPPED, toCsv(engine.skippedActivities()));
		configManager.setRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY_SKIPPED_PETS, toCsv(engine.petsSkippedActivities()));
	}

	private void persistBaseline()
	{
		configManager.setRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY_BASELINE, Integer.toString(baseline));
	}

	private void markAndPersist(int itemId)
	{
		boolean wasObtained = engine.isObtained(itemId);
		engine.markObtained(itemId);
		if (!wasObtained)
		{
			persist();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			// Defer one tick so RSProfile has the display name attached.
			clientThread.invokeLater(() ->
			{
				load();
				syncButton.reset();
				evaluateSyncStatus();
				return true;
			});
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			syncButton.reset();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		switch (event.getType())
		{
			case GAMEMESSAGE:
			case SPAM:
				break;
			default:
				return;
		}
		String message = Text.removeTags(event.getMessage());
		if (!message.startsWith(NEW_ITEM_PREFIX))
		{
			return;
		}
		// A new collection log unlock advances the player's COLLECTION_COUNT by one and we
		// just captured it — keep the baseline in lockstep so this doesn't read as drift.
		// (Only once a baseline exists; a never-synced account stays out of sync until a
		// full Sync so we still nudge it to run one.)
		if (baseline >= 0)
		{
			baseline++;
			persistBaseline();
		}
		String itemName = message.substring(NEW_ITEM_PREFIX.length()).trim();
		Integer id = itemIdsByName.get(itemName.toLowerCase());
		if (id == null)
		{
			log.debug("Could not resolve collection log item name: {}", itemName);
		}
		else
		{
			markAndPersist(id);
		}
		evaluateSyncStatus();
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == SCRIPT_COLLECTION_SETUP)
		{
			// The interface was (re)built — its dynamic children were wiped, so re-attach.
			syncButton.reset();
			attachButton();
			// Another plugin (e.g. Temple-OSRS) may also handle 7797 and call deleteAllChildren()
			// on this same container AFTER us, deleting our button. Re-attach once more on the next
			// client cycle — after every 7797 subscriber has run — so we survive that wipe
			// regardless of EventBus ordering. attach() is idempotent → a no-op when nothing wiped us.
			clientThread.invokeLater(() ->
			{
				attachButton();
				return true;
			});
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != SCRIPT_COLLECTION_ITEM)
		{
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if (args == null || args.length < 2)
		{
			return;
		}
		int itemId = (int) args[1];
		if (itemId > 0)
		{
			harvest.add(itemId);
		}
		// Push the consume out to a few ticks after the LAST item so a large log finishes
		// streaming before we read it.
		gameTickToSync = client.getTickCount() + SYNC_SETTLE_TICKS;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Self-heal: if the collection log is open but our button was removed by another plugin
		// wiping the container's children, re-create it. attach() no-ops when the log is closed
		// or our button is already present.
		attachButton();

		if (fullSyncRequested)
		{
			// A collection-log redraw can rebuild the button and revert it to "Sync";
			// re-pin the busy label each tick until we consume.
			syncButton.setBusy(true);
		}
		if (gameTickToSync == null || client.getTickCount() < gameTickToSync)
		{
			return;
		}
		consumeHarvest();
	}

	/** Builds the Sync button on the collection log header unless the user has hidden it. */
	private void attachButton()
	{
		if (!hideSyncButton.getAsBoolean())
		{
			syncButton.attach(client, this::triggerFullSync);
		}
	}

	/** Applies a flip of the "hide Log Sync button" option to a collection log that is already
	 *  open; a closed log just picks it up the next time it is built. Client thread. */
	public void onHideSyncButtonChanged()
	{
		if (hideSyncButton.getAsBoolean())
		{
			syncButton.detach();
		}
		else
		{
			attachButton();
		}
	}

	/** Press the in-game Search and run the enumerate script; harvested in onScriptPreFired. */
	private void triggerFullSync()
	{
		harvest.clear();
		fullSyncRequested = true;
		// Guarantee a consume even if the log is empty (no 4100 fires) so the button never
		// gets stuck on "Syncing..."; streaming items push this out further (see 4100).
		gameTickToSync = client.getTickCount() + SYNC_SETTLE_TICKS;
		syncButton.setBusy(true);
		notifySyncing(true);
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(SCRIPT_ENUMERATE_LOG);
	}

	/** Merge every harvested item into the obtained set and re-baseline. Client thread. */
	private void consumeHarvest()
	{
		int added = 0;
		for (int itemId : harvest)
		{
			if (!engine.isObtained(itemId))
			{
				added++;
			}
		}
		// Merge in one shot: a per-item markObtained() fires the listener fan-out (and a full
		// panel rebuild on the EDT) once per new item, which on a first-time sync is thousands
		// of rebuilds and locks up the client's mouse input until they drain.
		engine.markObtainedAll(harvest);
		if (added > 0)
		{
			persist();
		}
		log.debug("Collection log harvest: {} items seen, {} newly obtained (fullSync={})",
			harvest.size(), added, fullSyncRequested);
		harvest.clear();
		gameTickToSync = null;

		if (fullSyncRequested)
		{
			fullSyncRequested = false;
			syncButton.setBusy(false);
			notifySyncing(false);
			// A full sync makes us complete: pin the baseline to the player's true count.
			int pc = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
			if (pc > 0)
			{
				baseline = pc;
				migrationDone = true;
				persistBaseline();
			}
		}
		evaluateSyncStatus();
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() == VarPlayerID.COLLECTION_COUNT)
		{
			evaluateSyncStatus();
		}
	}

	/**
	 * Recomputes {@link #inSync} from the player's true count vs. the baseline, runs the
	 * one-shot migration when no baseline is stored yet, and fans out to listeners.
	 */
	public void evaluateSyncStatus()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		int pc = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		playerCount = pc;
		if (pc <= 0)
		{
			// Varp not delivered yet, or a fresh account with no logged items — don't warn.
			inSync = true;
			fire();
			return;
		}
		if (!migrationDone && baseline < 0)
		{
			// First run on this build. An existing user (recorded data from the old
			// per-page sync) is treated as already synced; a brand-new user is nudged
			// to run a full Sync.
			if (obtainedCountAtLogin > 0)
			{
				baseline = pc;
				persistBaseline();
			}
			migrationDone = true;
		}
		inSync = baseline >= 0 && pc <= baseline;
		fire();
	}

	public boolean isInSync()
	{
		return inSync;
	}

	public int playerClogCount()
	{
		return playerCount;
	}

	public void addSyncListener(Runnable r)
	{
		syncListeners.add(r);
	}

	/** Set the listener notified when a full sync starts (true) / finishes (false). */
	public void setSyncingListener(java.util.function.Consumer<Boolean> l)
	{
		this.syncingListener = l;
	}

	private void notifySyncing(boolean syncing)
	{
		if (syncingListener != null)
		{
			try
			{
				syncingListener.accept(syncing);
			}
			catch (RuntimeException ex)
			{
				log.warn("Syncing listener threw", ex);
			}
		}
	}

	private void fire()
	{
		for (Runnable l : syncListeners)
		{
			try
			{
				l.run();
			}
			catch (RuntimeException ex)
			{
				log.warn("Sync-status listener threw", ex);
			}
		}
	}

	private static Set<Integer> parseCsv(String csv)
	{
		if (csv == null || csv.isEmpty())
		{
			return new HashSet<>();
		}
		return Arrays.stream(csv.split(","))
			.map(String::trim)
			.filter(s -> !s.isEmpty())
			.map(s ->
			{
				try
				{
					return Integer.parseInt(s);
				}
				catch (NumberFormatException ex)
				{
					return null;
				}
			})
			.filter(java.util.Objects::nonNull)
			.collect(Collectors.toCollection(HashSet::new));
	}

	private static String toCsv(Set<Integer> ids)
	{
		if (ids.isEmpty())
		{
			return "";
		}
		StringBuilder sb = new StringBuilder(ids.size() * 6);
		boolean first = true;
		for (Integer id : ids)
		{
			if (!first)
			{
				sb.append(',');
			}
			sb.append(id);
			first = false;
		}
		return sb.toString();
	}

	// Convenience for slot lookups by item id (used by panel for display names).
	public LogSlot slotFor(int itemId)
	{
		return staticData.slotsByItemId().get(itemId);
	}
}

package com.logadviser.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.text.NumberFormat;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JWindow;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import lombok.Value;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * A small floating window listing an activity's collection-log slots — missing first, then
 * collected (greyed with a check). Capped in size with a vertical scrollbar so long activities
 * scroll instead of growing off-screen. Non-focusable so it never steals focus or intercepts
 * clicks meant for the panel. All methods must be called on the EDT.
 */
final class ActivityLogPopup
{
	// The popup is a fixed-size box. The body never resizes to fit the content, so a small
	// activity shows trailing empty space rather than a shrunken window, and the vertical
	// scrollbar appears only when the rows genuinely overflow this height.
	static final int FIXED_W = 250;
	static final int FIXED_H = 300;
	private static final int ICON_SIZE = 24;
	private static final Color COLLECTED_COLOR = new Color(120, 120, 120);
	private static final Color RATE_COLOR = new Color(160, 160, 160);

	/** Pre-resolved row data, snapshotted on the EDT so the hover path never reads the engine.
	 *  {@code slotDifficulty} / {@code dropRateAttempts} are the engine's "easiest" sort keys
	 *  (lower difficulty = easier, tie-broken by fewer attempts) and the drop rate to display. */
	@Value
	static final class SlotEntry
	{
		int itemId;
		String name;
		boolean collected;
		int slotDifficulty;
		double dropRateAttempts;
	}

	private final ItemManager itemManager;
	private final JWindow window;
	private final JLabel header;
	private final JPanel rows;

	ActivityLogPopup(ItemManager itemManager)
	{
		this.itemManager = itemManager;

		window = new JWindow();
		window.setFocusableWindowState(false);
		window.setFocusable(false);

		JPanel root = new JPanel(new BorderLayout());
		root.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		root.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));

		header = new JLabel();
		header.setForeground(Color.WHITE);
		header.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		root.add(header, BorderLayout.NORTH);

		rows = new ScrollableContent();
		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		rows.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JScrollPane scroll = new JScrollPane(rows);
		scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
		scroll.setBorder(null);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		// Match the empty area shown below the rows when an activity has only a few items.
		scroll.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);
		root.add(scroll, BorderLayout.CENTER);

		window.setContentPane(root);
		// Fixed window size: BorderLayout gives the header its natural height and the scroll
		// pane the rest, so the viewport is constant and only scrolls when the rows overflow.
		window.setSize(FIXED_W, FIXED_H);
	}

	/** Rebuilds the body for one activity. {@code slots} must already be ordered missing-first. */
	void setContent(String activityName, List<SlotEntry> slots)
	{
		int total = slots.size();
		int got = 0;
		for (SlotEntry s : slots)
		{
			if (s.isCollected())
			{
				got++;
			}
		}
		header.setText("<html><b>" + escape(activityName) + "</b><br>"
			+ got + "/" + total + " collected</html>");

		rows.removeAll();
		if (slots.isEmpty())
		{
			JLabel empty = new JLabel("No tracked log slots");
			empty.setForeground(Color.GRAY);
			empty.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
			empty.setAlignmentX(Component.LEFT_ALIGNMENT);
			rows.add(empty);
		}
		else
		{
			for (SlotEntry s : slots)
			{
				rows.add(buildRow(s));
			}
		}
		rows.revalidate();
		rows.repaint();
		// Window size stays fixed (set once in the constructor); the scrollbar appears only
		// when these rows are taller than the fixed viewport.
	}

	private JPanel buildRow(SlotEntry s)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 6));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		setIconAsync(icon, s.getItemId());
		row.add(icon, BorderLayout.WEST);

		JLabel name = new JLabel(s.isCollected() ? s.getName() + " ✔" : s.getName());
		name.setForeground(s.isCollected() ? COLLECTED_COLOR : Color.WHITE);
		// The row tracks the viewport width, so a long name is clipped to make room for the rate;
		// the full name stays available on hover.
		name.setToolTipText(s.getName());
		row.add(name, BorderLayout.CENTER);

		String rate = formatRate(s.getDropRateAttempts());
		if (rate != null)
		{
			JLabel rateLabel = new JLabel(rate);
			rateLabel.setForeground(RATE_COLOR);
			rateLabel.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 0));
			row.add(rateLabel, BorderLayout.EAST);
		}

		// Keep rows at their natural height under the Y_AXIS BoxLayout instead of stretching.
		row.setMaximumSize(new Dimension(FIXED_W, row.getPreferredSize().height));
		return row;
	}

	/** Per-item drop rate as "1/N". Returns null for non-positive rates (no meaningful drop). */
	private static String formatRate(double k)
	{
		if (k <= 0.0)
		{
			return null;
		}
		if (k < 1.0)
		{
			// Sub-1 means more than one per completion; show one decimal rather than rounding to 0.
			return "1/" + (Math.round(k * 10.0) / 10.0);
		}
		return "1/" + NumberFormat.getIntegerInstance().format(Math.round(k));
	}

	private void setIconAsync(JLabel label, int itemId)
	{
		if (itemId <= 0 || itemManager == null)
		{
			return;
		}
		AsyncBufferedImage image = itemManager.getImage(itemId);
		if (image == null)
		{
			return;
		}
		label.setIcon(new ImageIcon(image));
		image.onLoaded(() -> SwingUtilities.invokeLater(() ->
			label.setIcon(new ImageIcon((BufferedImage) image))));
	}

	void showAt(int screenX, int screenY)
	{
		window.setLocation(screenX, screenY);
		window.setVisible(true);
	}

	boolean isShowing()
	{
		return window.isVisible();
	}

	Rectangle getBoundsOnScreen()
	{
		return window.isVisible() ? window.getBounds() : null;
	}

	void hide()
	{
		window.setVisible(false);
	}

	void dispose()
	{
		window.dispose();
	}

	private static String escape(String s)
	{
		return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;");
	}

	/**
	 * Rows container that always matches the scroll pane's viewport width (never its own, wider
	 * content width). When the vertical scrollbar appears the viewport narrows and the rows reflow,
	 * so a long item name is clipped instead of pushing the right-aligned drop rate out of view.
	 * Height is left free so the panel can grow taller than the viewport and scroll vertically.
	 */
	private static final class ScrollableContent extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return orientation == SwingConstants.VERTICAL ? visibleRect.height : visibleRect.width;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

