	private String modeBadgeText(AccountMode mode, boolean detectedIronman)
	{
		String detected = detectedIronman ? "Iron" : "Main";
		switch (mode)
		{
			case MAIN:
				return "Main" + (detectedIronman ? " (overridden)" : "");
			case IRONMAN:
				return "Iron" + (detectedIronman ? "" : " (overridden)");
			case AUTO:
			default:
				return detected + " (auto)";
		}
	}

	// Builds the "Show" trigger button and its checkbox popup. Plain JCheckBoxes (not
	// JCheckBoxMenuItems) are added to the JPopupMenu so toggling one does NOT close the popup —
	// the user can tick several before clicking away. Categories union; Pets Only is exclusive.
	private void buildFilterControl()
	{
		filterTrigger.setHorizontalAlignment(SwingConstants.LEFT);
		// Reserve room on the right so a long summary never runs under the painted arrow.
		filterTrigger.setMargin(new Insets(2, 6, 2, 18));
		filterTrigger.setFocusable(false);
		// Record when the popup closes so clicking an open trigger toggles it shut: the click's
		// mouse-press cancels the popup grab (firing this listener), then the trigger's action fires
		// on release — if that release lands right after the close, treat it as the toggle, not a reopen.
		filterPopup.addPopupMenuListener(new PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(PopupMenuEvent e)
			{
			}

			@Override
			public void popupMenuWillBecomeInvisible(PopupMenuEvent e)
			{
				filterPopupHiddenAt = System.currentTimeMillis();
			}

			@Override
			public void popupMenuCanceled(PopupMenuEvent e)
			{
			}
		});
		filterTrigger.addActionListener(e ->
		{
			if (System.currentTimeMillis() - filterPopupHiddenAt > 200)
			{
				filterPopup.show(filterTrigger, 0, filterTrigger.getHeight());
			}
		});

		filterPopup.setBackground(ColorScheme.DARK_GRAY_COLOR);

		for (ShowFilter f : ShowFilter.values())
		{
			JCheckBox cb = new JCheckBox(f.displayName(), false);
			cb.setForeground(Color.LIGHT_GRAY);
			cb.setBackground(ColorScheme.DARK_GRAY_COLOR);
			cb.setFocusable(false);
			cb.addActionListener(e ->
			{
				// Categories and Pets Only are mutually exclusive: picking a category leaves pets mode.
				if (cb.isSelected())
				{
					petsOnlyBox.setSelected(false);
				}
				applyFilter();
			});
			filterBoxes.put(f, cb);
			filterPopup.add(cb);
		}

		filterPopup.addSeparator();

		petsOnlyBox.setForeground(Color.LIGHT_GRAY);
		petsOnlyBox.setBackground(ColorScheme.DARK_GRAY_COLOR);
		petsOnlyBox.setFocusable(false);
		petsOnlyBox.setToolTipText("Re-frame the ranking around the pets you still need "
			+ "(exclusive — ignores the category selection)");
		petsOnlyBox.addActionListener(e ->
		{
			// Pets Only clears every category tick so the two modes never apply at once.
			if (petsOnlyBox.isSelected())
			{
				for (JCheckBox cb : filterBoxes.values())
				{
					cb.setSelected(false);
				}
			}
			applyFilter();
		});
		filterPopup.add(petsOnlyBox);

		updateFilterSummary();
	}

	private void applyFilter()
	{
		boolean pets = petsOnlyBox.isSelected();
		EnumSet<ShowFilter> selected = EnumSet.noneOf(ShowFilter.class);
		if (!pets)
		{
			for (Map.Entry<ShowFilter, JCheckBox> e : filterBoxes.entrySet())
			{
				if (e.getValue().isSelected())
				{
					selected.add(e.getKey());
				}
			}
		}
		// Keep the EDT-side view flag in step with the mode before any repaint, so the renderer and
		// current card pick it up. The show-filter is stored first (no recompute); the pets toggle
		// is marshalled to the client thread and its recompute fires the authoritative snapshot last.
		// In pets mode the show-filter is left empty (= All) so the pet ranking sees every category.
		petsOnlyView = pets;
		engine.setShowFilter(selected);
		if (onPetsOnlyChanged != null)
		{
			onPetsOnlyChanged.accept(pets);
		}
		updateFilterSummary();
	}

	// Reflects the current selection on the trigger button: "Pets Only", "All" (nothing ticked),
	// or the ticked categories joined in enum order (e.g. "Combat, Slayer").
	private void updateFilterSummary()
	{
		String summary;
		if (petsOnlyBox.isSelected())
		{
			summary = "Pets Only";
		}
		else
		{
			StringBuilder sb = new StringBuilder();
			for (Map.Entry<ShowFilter, JCheckBox> e : filterBoxes.entrySet())
			{
				if (e.getValue().isSelected())
				{
					if (sb.length() > 0)
					{
						sb.append(", ");
					}
					sb.append(e.getKey().displayName());
				}
			}
			summary = sb.length() == 0 ? "All" : sb.toString();
		}
		// Arrow is painted separately (see field); the text holds just the summary.
		filterTrigger.setText(summary);
	}

	public void onRankingChanged(List<RankedActivity> ranking)
	{
		// Park the newest snapshot and only queue a rebuild if one isn't already pending —
		// the queued task always applies the latest snapshot, so intermediate ones are dropped
		// instead of each costing a full (and immediately superseded) rebuild on the EDT.
		if (pendingRanking.getAndSet(new ArrayList<>(ranking)) != null)
		{
			return;
		}
		SwingUtilities.invokeLater(() ->
		{
			List<RankedActivity> snapshot = pendingRanking.getAndSet(null);
			if (snapshot != null)
			{
				applyRanking(snapshot);
			}
		});
	}

	private void applyRanking(List<RankedActivity> ranking)
	{
		if (log.isDebugEnabled())
		{
			StringBuilder lockedAt = new StringBuilder();
			for (int i = 0; i < ranking.size(); i++)
			{
				RankedActivity r = ranking.get(i);
				if (r.isLocked())
				{
					lockedAt.append(' ').append('#').append(i)
						.append("=idx").append(r.getActivity().getIndex());
				}
			}
			log.debug("Panel#{} applyRanking: size={}, lockedPositions=[{}]",
				System.identityHashCode(this), ranking.size(), lockedAt.toString().trim());
		}

		lastRanking = ranking;

		// Snapshot each activity's log slots on the EDT so the hover preview never reads the
		// engine off the client thread. Rebuilt every ranking change so it stays current.
		slotSnapshot.clear();
		for (RankedActivity r : ranking)
		{
			int idx = r.getActivity().getIndex();
			slotSnapshot.put(idx, buildSlotEntries(idx));
		}
		// Skipped activities are absent from the normal ranking but still hoverable in the
		// skip-list view, so snapshot them too.
		for (RankedActivity r : engine.getSkippedRanking())
		{
			int idx = r.getActivity().getIndex();
			slotSnapshot.computeIfAbsent(idx, this::buildSlotEntries);
		}

		// The current-target card should never point at a locked activity — surface the
		// first one the player can actually do.
		RankedActivity top = null;
		for (RankedActivity r : ranking)
		{
			if (!r.isLocked())
			{
				top = r;
				break;
			}
		}

		if (top == null)
		{
			currentTopRanked = null;
			currentItem.setText(ranking.isEmpty()
				? (petsOnlyView ? "All available pets collected" : "All filtered activities complete")
				: "All available activities complete");
			currentActivity.setText(ranking.isEmpty() ? " " : "(remaining activities are locked)");
			currentHint.setText(" ");
			currentTime.setText(" ");
			currentIcon.setIcon(null);
			skipButton.setEnabled(false);
			refreshListView();
			updateCounts();
			return;
		}

		currentTopRanked = top;
		ActivityItem display = top.getDisplayItem() != null ? top.getDisplayItem() : top.getFastestItem();
		String itemName = display != null ? safeName(display.getItemId(), display.getItemName()) : "—";
		currentItem.setText(itemName);
		currentActivity.setText(top.getActivity().getName());
		ActivityNpcInfo info = staticData.npcInfoFor(top.getActivity().getIndex());
		currentHint.setText(info.getHint().isEmpty() ? "(see activity name)" : info.getHint());
		currentTime.setText("~ " + TargetInfoBox.formatHours(top.getTimeToNextSlotHours())
			+ (petsOnlyView ? " to pet" : " to slot"));
		setIconAsync(currentIcon, display != null ? display.getItemId() : 0);
		skipButton.setEnabled(true);

		refreshListView();
		updateCounts();
	}

	/** Repopulates the list box for the active mode: the skipped activities when
	 *  the skip list is toggled on, otherwise the normal ranking. Must run on the EDT. */
	private void refreshListView()
	{
		listModel.clear();
		if (showingSkipList)
		{
			for (RankedActivity r : engine.getSkippedRanking())
			{
				listModel.addElement(r);
			}
			registerIconRefresh();
			forceListRelayout();
			return;
		}
		int desired = upcomingListSize.getAsInt();
		if (desired <= 0)
		{
			desired = 30;
		}
		// Only unlocked activities count toward the size cap; locked ones are always
		// appended at the bottom (also capped) so the player can see what to unlock
		// next instead of them being buried past the cap.
		int shownUnlocked = 0;
		List<RankedActivity> lockedRows = new ArrayList<>();
		for (RankedActivity r : lastRanking)
		{
			if (r.isLocked())
			{
				if (lockedRows.size() < desired)
				{
					lockedRows.add(r);
				}
			}
			else if (shownUnlocked < desired)
			{
				listModel.addElement(r);
				shownUnlocked++;
			}
		}
		for (RankedActivity r : lockedRows)
		{
			listModel.addElement(r);
		}
		registerIconRefresh();
		forceListRelayout();
	}

	/** Forces the JList to recompute its variable cell heights after a model rebuild. The list
	 *  uses a variable-height HTML renderer (no fixed cell height), and BasicListUI can leave some
	 *  rows with a stale/zero cached height when the model is rebuilt while the panel isn't showing
	 *  — those rows stay blank until a click recomputes the layout. Toggling fixedCellHeight fires
	 *  the property change that invalidates that cache, so every row paints immediately. */
	private void forceListRelayout()
	{
		list.setFixedCellHeight(10);
		list.setFixedCellHeight(-1);
		list.revalidate();
		list.repaint();
	}

	/** Repaints the list once each row's item icon finishes loading. The cell
	 *  renderer reuses one shared label and can't refresh itself, so a single
	 *  list-wide repaint per load lets the renderer pick up the now-cached image.
	 *  Runs once per refresh (not per paint) to avoid a repaint loop. */
	private void registerIconRefresh()
	{
		if (itemManager == null)
		{
			return;
		}
		for (int i = 0; i < listModel.size(); i++)
		{
			RankedActivity r = listModel.get(i);
			ActivityItem display = r.getDisplayItem() != null
				? r.getDisplayItem() : r.getFastestItem();
			if (display == null)
			{
				continue;
			}
			AsyncBufferedImage img = itemManager.getImage(display.getItemId());
			if (img != null)
			{
				img.onLoaded(() -> SwingUtilities.invokeLater(list::repaint));
			}
		}
	}

	private String safeName(int itemId, String fallback)
	{
		LogSlot slot = staticData.slotsByItemId().get(itemId);
		return slot != null ? slot.getSlotName() : (fallback != null ? fallback : "Item " + itemId);
	}

	private void setIconAsync(JLabel label, int itemId)
	{
		if (itemId <= 0 || itemManager == null)
		{
			label.setIcon(null);
			return;
		}
		AsyncBufferedImage image = itemManager.getImage(itemId);
		if (image == null)
		{
			label.setIcon(null);
			return;
		}
		label.setIcon(new ImageIcon(image));
		image.onLoaded(() -> SwingUtilities.invokeLater(() -> label.setIcon(new ImageIcon((BufferedImage) image))));
	}

	private static JPanel verticalGap(int h)
	{
		JPanel p = new JPanel();
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		p.setPreferredSize(new Dimension(1, h));
		return p;
	}

	private final class RankRenderer extends DefaultListCellRenderer
	{
		// Reserve room for the icon + padding; HTML body wraps at this width.
		private static final int TEXT_WIDTH = PluginPanel.PANEL_WIDTH - 90;

		@Override
		public Component getListCellRendererComponent(
			JList<?> list, Object value, int index, boolean selected, boolean focus)
		{
			JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, selected, focus);
			if (value instanceof RankedActivity)
			{
				RankedActivity r = (RankedActivity) value;
				ActivityItem display = r.getDisplayItem() != null ? r.getDisplayItem() : r.getFastestItem();
				String name = r.getActivity().getName();
				String secondLine;
				if (r.isLocked())
				{
					String req = r.getRequirementLabel() == null ? "" : escape(r.getRequirementLabel());
					secondLine = "<span style='color:#c08a3e'>LOCKED</span>"
						+ " - req: " + req;
				}
				else
				{
					String time = TargetInfoBox.formatHours(r.getTimeToNextSlotHours());
					String timeSpan = "<span style='color:#9bc7ff'>~ " + time + "</span>";
					// Pets mode times the pet drop alone, so the slot x/x count is meaningless here.
					secondLine = petsOnlyView
						? timeSpan
						: timeSpan + " - " + (r.getSlotsTotal() - r.getSlotsLeft()) + "/" + r.getSlotsTotal();
				}
				// Explicit body width so Swing's HTML renderer word-wraps long names
				// instead of pushing the cell past the viewport (and adding a hscroll).
				label.setText("<html><body style='width:" + TEXT_WIDTH + "px'>"
					+ "<b>" + escape(name) + "</b><br>"
					+ secondLine
					+ "</body></html>");
				label.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
				label.setVerticalAlignment(SwingConstants.TOP);
				label.setVerticalTextPosition(SwingConstants.TOP);
				if (display != null && itemManager != null)
				{
					AsyncBufferedImage img = itemManager.getImage(display.getItemId());
					if (img != null)
					{
						label.setIcon(new ImageIcon(img));
					}
				}
				else
				{
					label.setIcon(null);
				}
			}
			if (!selected)
			{
				label.setBackground(ColorScheme.DARK_GRAY_COLOR);
				boolean locked = value instanceof RankedActivity && ((RankedActivity) value).isLocked();
				label.setForeground(locked ? new Color(130, 130, 130) : Color.LIGHT_GRAY);
			}
			return label;
		}

		private String escape(String s)
		{
			return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;");
		}
	}
}

package com.logadviser.ui;

import com.logadviser.engine.RankedActivity;
import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

public class TargetInfoBox extends InfoBox
{
	private final String itemName;
	private final String activityName;
	private final String hint;
	private final double timeHours;
	private final int slotsLeft;
	private final int slotsTotal;
	private final boolean fullySynced;

	public TargetInfoBox(BufferedImage image, Plugin plugin, RankedActivity ranked, String itemName, String hint,
		boolean fullySynced)
	{
		super(image, plugin);
		this.itemName = itemName;
		this.activityName = ranked.getActivity().getName();
		this.hint = hint;
		this.timeHours = ranked.getTimeToNextSlotHours();
		this.slotsLeft = ranked.getSlotsLeft();
		this.slotsTotal = ranked.getSlotsTotal();
		this.fullySynced = fullySynced;
	}

	private static final Color STALE = new Color(255, 152, 0);

	@Override
	public String getText()
	{
		// Visible stale marker on the icon itself when the collection log isn't synced.
		return fullySynced ? null : "!";
	}

	@Override
	public Color getTextColor()
	{
		return fullySynced ? Color.WHITE : STALE;
	}

	@Override
	public String getTooltip()
	{
		// RuneLite tooltips use Jagex tag syntax (<col=hex>...</col>, <br>) — NOT HTML.
		// Wrapping in <html><b>...</b></html> renders the markup literally.
		StringBuilder sb = new StringBuilder();
		sb.append("Next log slot: <col=ffff00>").append(itemName).append("</col><br>");
		sb.append("Activity: ").append(activityName).append("<br>");
		if (hint != null && !hint.isEmpty())
		{
			sb.append("How: <col=aaaaaa>").append(hint).append("</col><br>");
		}
		sb.append("Time to slot: <col=9bc7ff>").append(formatHours(timeHours)).append("</col><br>");
		sb.append("Progress: ").append(slotsTotal - slotsLeft).append(" / ").append(slotsTotal);
		if (!fullySynced)
		{
			sb.append("<br><col=8a8a8a>Data may be stale — open the collection log and click Sync</col>");
		}
		return sb.toString();
	}

	static String formatHours(double hours)
	{
		if (Double.isInfinite(hours) || Double.isNaN(hours))
		{
			return "n/a";
		}
		double totalSeconds = hours * 3600.0;
		if (totalSeconds < 90)
		{
			return String.format("%.0fs", totalSeconds);
		}
		if (totalSeconds < 3600)
		{
			return String.format("%.0fm", totalSeconds / 60.0);
		}
		long h = (long) hours;
		if (h > 10)
		{
			return h + "h";
		}
		long m = (long) ((hours - h) * 60.0);
		return m == 0 ? h + "h" : h + "h " + m + "m";
	}

}

package com.logadviser.ui;

import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.RankedActivity;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Box rendered on top of the game viewport (top-right by default, draggable). Mirrors
 * the InfoBox content but is much harder to miss — useful when you want the active
 * step staring at you while you're playing rather than buried in the corner tray.
 */
public class TargetTextOverlay extends OverlayPanel
{
	private static final Color BLUE = new Color(155, 199, 255);
	private static final Color YELLOW = new Color(255, 234, 100);
	private static final Color GRAY = new Color(180, 180, 180);
	private static final Color WHITE = new Color(230, 230, 230);
	private static final int PANEL_WIDTH = 240;

	private final AdviserEngine engine;
	private volatile RankedActivity current;
	private volatile String itemName = "";
	private volatile String hint = "";

	public TargetTextOverlay(AdviserEngine engine)
	{
		this.engine = engine;
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPosition(OverlayPosition.TOP_RIGHT);
		setPriority(OverlayPriority.LOW);
		// Wider than the default so long activity names ("Killing the nightmare of
		// ashihama (5 person team)") don't collide with right-aligned values.
		getPanelComponent().setPreferredSize(new Dimension(PANEL_WIDTH, 0));
	}

	public void setTarget(RankedActivity ranked, String itemName, String hint)
	{
		this.current = ranked;
		this.itemName = itemName == null ? "" : itemName;
		this.hint = hint == null ? "" : hint;
	}

	public void clearTarget()
	{
		this.current = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		RankedActivity r = current;
		if (r == null)
		{
			return null;
		}
		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Log Adviser")
			.color(BLUE)
			.build());

		// Item slot — full-width yellow line (the headline).
		panelComponent.getChildren().add(LineComponent.builder()
			.left(itemName)
			.leftColor(YELLOW)
			.build());

		// Activity name — full-width on its own row so long names use the entire
		// panel width instead of being squeezed into a right-aligned column.
		panelComponent.getChildren().add(LineComponent.builder()
			.left(r.getActivity().getName())
			.leftColor(WHITE)
			.build());

		// Hint — full-width gray line, wraps automatically.
		if (!hint.isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(hint)
				.leftColor(GRAY)
				.build());
		}

		// Compact left/right summary rows — these short values fit cleanly.
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Time")
			.leftColor(GRAY)
			.right(TargetInfoBox.formatHours(r.getTimeToNextSlotHours()))
			.rightColor(BLUE)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Activity logs")
			.leftColor(GRAY)
			.right((r.getSlotsTotal() - r.getSlotsLeft()) + " / " + r.getSlotsTotal())
			.rightColor(WHITE)
			.build());

		return super.render(graphics);
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.ActivityRequirements;
import com.logadviser.data.QuestResolver;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.PlayerProgress;
import com.logadviser.engine.RankedActivity;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;

/**
 * Proves the skill/quest gating end-to-end against the real activity_requirements.json,
 * with no RuneLite client involved — so a failure here is a code bug, and a pass means
 * any in-client failure is a stale-build / wrong-launch-path issue.
 */
public class ActivityRequirementsTest
{
	// Quest tokens intentionally present in activity_requirements.json but not yet in the
	// released RuneLite Quest enum (the build resolves 'latest.release'). QuestResolver returns
	// null for these, so the gate stays inert until a RuneLite release adds the quest, at which
	// point it activates automatically. Listed here (normalised lower-case) so
	// everyQuestTokenResolves treats them as pending rather than as typos. Remove an entry once
	// RuneLite ships the quest.
	// "The Blood Moon Rises" was removed from this list once RuneLite shipped it (the running
	// build resolves it, so the guard now covers that token again).
	private static final Set<String> PENDING_QUESTS = new HashSet<>(Collections.singletonList(
		"fallen from grace"));

	private StaticData data;

	@Before
	public void setUp() throws Exception
	{
		data = StaticDataLoader.loadAll(new Gson());
	}

	@Test
	public void requirementsJsonLoaded()
	{
		assertFalse("activity_requirements.json produced no entries — resource not on "
			+ "the classpath or failed to parse", data.getRequirementsByActivity().isEmpty());

		// Skill-only entries.
		assertEquals(Integer.valueOf(85), data.requirementsFor(1).getSkillLevels().get(Skill.SLAYER));
		assertEquals(Integer.valueOf(95), data.requirementsFor(2).getSkillLevels().get(Skill.SLAYER));
		assertTrue("activity 1 has no quest gate", data.requirementsFor(1).getQuests().isEmpty());

		// Skill + quest entry: 47 = Slayer 51 + Troubled Tortugans.
		ActivityRequirements a47 = data.requirementsFor(47);
		assertEquals(Integer.valueOf(51), a47.getSkillLevels().get(Skill.SLAYER));
		assertEquals("Troubled Tortugans", questName(a47, "Troubled Tortugans"));

		// Quest-only entry: 251 = The Ides of Milk.
		assertEquals("The Ides of Milk",
			questName(data.requirementsFor(251), "The Ides of Milk"));

		// A multi-word, punctuated quest name must resolve too.
		assertEquals("Desert Treasure II - The Fallen Empire",
			questName(data.requirementsFor(17), "Desert Treasure II - The Fallen Empire"));
	}

	@Test
	public void everyQuestTokenResolves()
	{
		StringBuilder unresolved = new StringBuilder();
		for (Map.Entry<Integer, ActivityRequirements> e
			: data.getRequirementsByActivity().entrySet())
		{
			ActivityRequirements r = e.getValue();
			for (String q : r.getRawQuestStrings())
			{
				// A pending quest (not yet in the running RuneLite's Quest enum) is allowed to be
				// unresolved; any other token that fails to resolve is a real typo. Once RuneLite
				// ships the quest, resolve() returns non-null and this still passes — remove the
				// allowlist entry then so the guard resumes catching that token.
				if (QuestResolver.resolve(q) == null
					&& !PENDING_QUESTS.contains(q.trim().toLowerCase()))
				{
					unresolved.append("\n  activity ").append(e.getKey())
						.append(": unresolved quest '").append(q).append('\'');
				}
			}
		}
		assertEquals("some quest tokens did not resolve to a RuneLite Quest:"
			+ unresolved, 0, unresolved.length());
	}

	@Test
	public void bloodMoonGateActivatesWhenRuneLiteKnowsTheQuest()
	{
		// "The Blood Moon Rises" gates activities 255 (Killing Maggot King) and 256 (Killing
		// Venators). It only reached RuneLite's Quest enum in 1.12.32; on older clients the token
		// is unresolvable, so this skips there and asserts once the running RuneLite has it —
		// proving the gate wires up (rather than silently doing nothing).
		Quest bloodMoon = QuestResolver.resolve("The Blood Moon Rises");
		assumeTrue("skipped: this RuneLite build has no 'The Blood Moon Rises' quest yet",
			bloodMoon != null);

		assertTrue("Blood Moon must be the resolved gate for activity 255",
			data.requirementsFor(255).getQuests().contains(bloodMoon));
		assertTrue("Blood Moon must be the resolved gate for activity 256",
			data.requirementsFor(256).getQuests().contains(bloodMoon));

		AdviserEngine engine = new AdviserEngine(data, () -> false);
		engine.setPlayerProgress(new PlayerProgress(
			new EnumMap<>(Skill.class), Collections.<Quest>emptySet()));
		List<RankedActivity> ranking = engine.getRanking();
		assertTrue("Killing Maggot King (255) is locked without the quest",
			find(ranking, 255).isLocked());
		assertTrue("Killing Venators (256) is locked without the quest",
			find(ranking, 256).isLocked());
		assertEquals("The Blood Moon Rises", find(ranking, 255).getRequirementLabel());

		Set<Quest> done = new HashSet<>();
		done.add(bloodMoon);
		engine.setPlayerProgress(new PlayerProgress(new EnumMap<>(Skill.class), done));
		assertFalse("255 unlocks once the quest is complete",
			find(engine.getRanking(), 255).isLocked());
	}

	@Test
	public void fallenFromGraceGateActivatesWhenRuneLiteKnowsTheQuest()
	{
		// "Fallen From Grace" gates the three Wyrmscraig activities: 257 (Golem crafting),
		// 258 (Hunting Wyrmscraig goats) and 259 (Killing Mad Angel). It shipped 29 July 2026
		// and only reaches RuneLite's Quest enum in a later release, so this skips on older
		// clients and asserts once the running RuneLite has it — proving the gate wires up
		// rather than silently doing nothing.
		Quest fallen = QuestResolver.resolve("Fallen From Grace");
		assumeTrue("skipped: this RuneLite build has no 'Fallen From Grace' quest yet",
			fallen != null);

		for (int idx : new int[]{257, 258, 259})
		{
			assertTrue("Fallen From Grace must be a resolved gate for activity " + idx,
				data.requirementsFor(idx).getQuests().contains(fallen));
		}

		// Max the gated skills so the quest is the only thing that can still hold these locked.
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.CRAFTING, 99);
		levels.put(Skill.HUNTER, 99);
		levels.put(Skill.SAILING, 99);

		AdviserEngine engine = new AdviserEngine(data, () -> false);
		engine.setPlayerProgress(new PlayerProgress(levels, Collections.<Quest>emptySet()));
		assertTrue("Golem crafting (257) stays locked on the quest alone",
			find(engine.getRanking(), 257).isLocked());
		assertTrue("Killing Mad Angel (259) stays locked on the quest alone",
			find(engine.getRanking(), 259).isLocked());

		// 258 is deliberately left out below: it also requires Sheep Herder, so completing
		// Fallen From Grace alone must not unlock it.
		Set<Quest> done = new HashSet<>();
		done.add(fallen);
		engine.setPlayerProgress(new PlayerProgress(levels, done));
		assertFalse("257 unlocks once the quest is complete",
			find(engine.getRanking(), 257).isLocked());
		assertFalse("259 unlocks once the quest is complete",
			find(engine.getRanking(), 259).isLocked());
	}

	@Test
	public void lowSlayerLocksAndDemotesGatedActivities()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);

		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.SLAYER, 27);
		engine.setPlayerProgress(new PlayerProgress(levels, Collections.<Quest>emptySet()));

		List<RankedActivity> ranking = engine.getRanking();

		RankedActivity act1 = find(ranking, 1);
		RankedActivity act2 = find(ranking, 2);
		assertTrue("activity 1 should be locked at 27 Slayer", act1.isLocked());
		assertTrue("activity 2 should be locked at 27 Slayer", act2.isLocked());
		assertEquals("85 Slayer", act1.getRequirementLabel());
		assertEquals("95 Slayer", act2.getRequirementLabel());

		// Every locked entry must sort after every unlocked entry.
		int firstLocked = -1;
		int lastUnlocked = -1;
		for (int i = 0; i < ranking.size(); i++)
		{
			if (ranking.get(i).isLocked())
			{
				if (firstLocked < 0)
				{
					firstLocked = i;
				}
			}
			else
			{
				lastUnlocked = i;
			}
		}
		assertTrue("locked activities must be demoted below all unlocked ones",
			firstLocked > lastUnlocked);
	}

	@Test
	public void meetingRequirementsUnlocks()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);
		Quest tortugans = data.requirementsFor(47).getQuests().get(0);

		// Slayer maxed but Troubled Tortugans not done → 47 still locked on the quest.
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.SLAYER, 99);
		engine.setPlayerProgress(new PlayerProgress(levels, Collections.<Quest>emptySet()));
		assertFalse("skill-only gate clears at 99 Slayer", find(engine.getRanking(), 1).isLocked());
		assertTrue("quest gate still locks 47", find(engine.getRanking(), 47).isLocked());
		assertEquals("Troubled Tortugans", find(engine.getRanking(), 47).getRequirementLabel());

		// Quest finished as well → 47 unlocks.
		Set<Quest> done = new HashSet<>();
		done.add(tortugans);
		engine.setPlayerProgress(new PlayerProgress(levels, done));
		assertFalse("47 unlocks once Slayer and quest are met",
			find(engine.getRanking(), 47).isLocked());
	}

	@Test
	public void ignoreRequirementsUnlocksEverything()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.SLAYER, 1);
		engine.setPlayerProgress(new PlayerProgress(levels, Collections.<Quest>emptySet()));
		assertTrue(find(engine.getRanking(), 1).isLocked());

		engine.setIgnoreRequirements(true);
		assertFalse("ignore-requirements must unlock gated activities",
			find(engine.getRanking(), 1).isLocked());
	}

	/** Asserts the requirement set resolved a quest whose display name matches, and
	 *  returns that name (so a resolution failure shows up as a clear assertion). */
	private static String questName(ActivityRequirements req, String expectedDisplay)
	{
		for (Quest q : req.getQuests())
		{
			if (q.getName().equals(expectedDisplay))
			{
				return q.getName();
			}
		}
		assertNotNull("quest '" + expectedDisplay + "' failed to resolve (got " + req.getQuests()
			+ ")", null);
		return null;
	}

	private static RankedActivity find(List<RankedActivity> ranking, int activityIndex)
	{
		for (RankedActivity r : ranking)
		{
			if (r.getActivity().getIndex() == activityIndex)
			{
				return r;
			}
		}
		throw new AssertionError("activity index " + activityIndex + " not in ranking");
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AdviserEngine;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The full collection-log sync merges its whole harvest through
 * {@link AdviserEngine#markObtainedAll}. Doing that item-by-item fired the listener fan-out once
 * per newly obtained item, and each fan-out queues a complete panel rebuild on the EDT — the same
 * thread RuneLite dispatches mouse events on — so a first-time sync froze the client's input for
 * as long as the backlog took to drain. These tests pin the batched behaviour and prove it agrees
 * with the per-item path it replaced.
 */
public class BulkMarkObtainedTest
{
	private StaticData data;
	private List<Integer> manyItemIds;

	@Before
	public void setUp() throws Exception
	{
		data = StaticDataLoader.loadAll(new Gson());
		manyItemIds = new ArrayList<>(data.slotsByItemId().keySet());
		// Guard the premise: the freeze only showed up because a real harvest is large.
		assertTrue("expected a large slot set to make this test meaningful",
			manyItemIds.size() > 100);
	}

	@Test
	public void markObtainedAllFiresListenersExactlyOnce()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);
		AtomicInteger fires = new AtomicInteger();
		engine.addListener(ranking -> fires.incrementAndGet());

		engine.markObtainedAll(manyItemIds);

		assertEquals("a whole harvest must cost exactly one listener fan-out", 1, fires.get());
	}

	@Test
	public void markObtainedAllMatchesPerItemMarking()
	{
		AdviserEngine bulk = new AdviserEngine(data, () -> false);
		AdviserEngine perItem = new AdviserEngine(data, () -> false);

		bulk.markObtainedAll(manyItemIds);
		for (int id : manyItemIds)
		{
			perItem.markObtained(id);
		}

		assertEquals("batched merge must record the same slots as the per-item path",
			perItem.collectedSlotCount(), bulk.collectedSlotCount());
		assertEquals("batched merge must store the same ids as the per-item path",
			perItem.obtainedItems(), bulk.obtainedItems());
		for (int id : manyItemIds)
		{
			// The obtained set holds canonical ids only (isObtained does no aliasing), so a
			// Body-type-B id is recorded under its Body-type-A twin — same as markObtained.
			assertTrue("item " + id + " should be obtained after the batched merge",
				bulk.isObtained(data.canonicalItemId(id)));
		}
	}

	@Test
	public void markObtainedAllIsSilentWhenNothingIsNew()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);
		engine.markObtainedAll(manyItemIds);

		AtomicInteger fires = new AtomicInteger();
		engine.addListener(ranking -> fires.incrementAndGet());
		// Re-syncing an already-complete log — the common case for an up-to-date account.
		engine.markObtainedAll(manyItemIds);

		assertEquals("a no-op merge must not recompute or notify", 0, fires.get());
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.RankedActivity;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Guards "icon follows the time": the headline display item must be the slot the time estimate
 * is for (the one driving {@code best}), not the lowest-difficulty slot. Regression for the bug
 * where Araxxor showed the non-guaranteed Noxious point icon next to the ~89s estimate that
 * actually belongs to the near-guaranteed Coagulated venom drop.
 */
public class DisplayItemTest
{
	// Araxxor ("Killing araxxor (on task)") and two of its drops.
	private static final int ARAXXOR_INDEX = 4;
	private static final int COAGULATED_VENOM = 29781; // dropRateAttempts 1.0 — drives the estimate
	private static final int NOXIOUS_POINT = 29790;    // dropRateAttempts 200.0 — the old (wrong) icon

	private StaticData data;

	@Before
	public void setUp() throws Exception
	{
		data = StaticDataLoader.loadAll(new Gson());
	}

	@Test
	public void displayItemIsTheSlotDrivingTheEstimateNotTheEasiestSlot()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);

		RankedActivity araxxor = find(engine.getRanking(), ARAXXOR_INDEX);
		assertNotNull("Araxxor (index " + ARAXXOR_INDEX + ") must be rankable", araxxor);

		assertNotNull("display item must be set for a rankable activity", araxxor.getDisplayItem());
		assertEquals(
			"display item must be the slot the time estimate is for (Coagulated venom), not the "
				+ "lowest-difficulty slot (Noxious point)",
			COAGULATED_VENOM,
			araxxor.getDisplayItem().getItemId());
		assertTrue(
			"the near-guaranteed driver makes the estimate fast — sanity-check it is not the "
				+ "non-guaranteed Noxious point's multi-hour time",
			araxxor.getTimeToNextSlotHours() < 0.05);
		assertTrue("Noxious point must not be the headline slot",
			araxxor.getDisplayItem().getItemId() != NOXIOUS_POINT);
	}

	private static RankedActivity find(List<RankedActivity> ranking, int activityIndex)
	{
		for (RankedActivity r : ranking)
		{
			if (r.getActivity().getIndex() == activityIndex)
			{
				return r;
			}
		}
		return null;
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AccountMode;
import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.RankedActivity;
import java.util.List;

/** Headless sanity check, run via `gradle dataSanity` or by main. */
public class EngineSanityCheck
{
	public static void main(String[] args) throws Exception
	{
		StaticData data = StaticDataLoader.loadAll(new Gson());
		System.out.println("activities:   " + data.getActivities().size());
		System.out.println("activityItems:" + data.getActivityItems().size());
		System.out.println("slots:        " + data.getSlots().size());
		System.out.println("npc maps:     " + data.getNpcInfoByActivity().size());

		AdviserEngine main = new AdviserEngine(data, () -> false);
		main.setAccountMode(AccountMode.MAIN);
		print("MAIN top 10", main.getRanking(), 10);

		AdviserEngine iron = new AdviserEngine(data, () -> true);
		iron.setAccountMode(AccountMode.IRONMAN);
		print("IRON top 10", iron.getRanking(), 10);

		// Mark gryphon feather obtained — top should change.
		RankedActivity top = main.getRanking().get(0);
		System.out.println();
		System.out.println("Marking " + top.getDisplayItem().getItemName()
			+ " (id=" + top.getDisplayItem().getItemId() + ") obtained");
		main.markObtained(top.getDisplayItem().getItemId());
		print("MAIN top 5 after one slot", main.getRanking(), 5);
	}

	private static void print(String header, List<RankedActivity> rs, int n)
	{
		System.out.println();
		System.out.println(header);
		for (int i = 0; i < Math.min(n, rs.size()); i++)
		{
			RankedActivity r = rs.get(i);
			double secs = r.getTimeToNextSlotHours() * 3600.0;
			System.out.printf("  %2d. %-60s  %s%n",
				i + 1,
				r.getActivity().getName(),
				secs < 90 ? String.format("%.1fs", secs)
					: secs < 3600 ? String.format("%.1fm", secs / 60.0)
					: String.format("%.2fh", r.getTimeToNextSlotHours()));
		}
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.LogSlot;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AdviserEngine;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Body-type-B Farmer's outfit items must canonicalise onto the Body-type-A ids that
 * live in slots.json, so a Body-type-B player's collection log syncs correctly.
 */
public class ItemAliasesTest
{
	// Body-type-B id -> canonical Body-type-A id (the ones present in slots.json).
	private static final int[][] FARMER_PAIRS = {
		{13641, 13640}, // boro trousers
		{13643, 13642}, // shirt/jacket
		{13645, 13644}, // boots
		{13647, 13646}, // strawhat
	};

	private StaticData data;

	@Before
	public void setUp() throws Exception
	{
		data = StaticDataLoader.loadAll(new Gson());
	}

	@Test
	public void slotsByItemIdResolvesBothBodyTypes()
	{
		Map<Integer, LogSlot> byId = data.slotsByItemId();
		for (int[] pair : FARMER_PAIRS)
		{
			int b = pair[0], a = pair[1];
			LogSlot slotA = byId.get(a);
			assertNotNull("canonical id " + a + " missing from slots.json", slotA);
			assertSame("Body-type-B id " + b + " must map to the same slot as " + a,
				slotA, byId.get(b));
		}
	}

	@Test
	public void canonicalItemIdMapsBToA()
	{
		for (int[] pair : FARMER_PAIRS)
		{
			assertEquals(pair[1], data.canonicalItemId(pair[0]));
			// Canonical ids and unrelated ids are returned unchanged.
			assertEquals(pair[1], data.canonicalItemId(pair[1]));
		}
	}

	@Test
	public void shirtJacketChatNamesResolve()
	{
		Map<String, Integer> byName = data.itemIdsByName();
		assertEquals(Integer.valueOf(13642), byName.get("farmer's jacket"));
		assertEquals(Integer.valueOf(13642), byName.get("farmer's shirt"));
	}

	@Test
	public void markObtainedCanonicalisesWithoutDoubleCount()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);
		int before = engine.collectedSlotCount();
		for (int[] pair : FARMER_PAIRS)
		{
			int b = pair[0], a = pair[1];
			engine.markObtained(b);             // Body-type-B item from the widget scrape
			assertTrue("canonical id " + a + " should be obtained after marking " + b,
				engine.isObtained(a));
			engine.markObtained(a);             // same slot via the other body type / chat
		}
		assertEquals("each Farmer's pair must count exactly once",
			before + FARMER_PAIRS.length, engine.collectedSlotCount());
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.StaticData;
