import com.google.gson.Gson;
import com.logadviser.data.Activity;
import com.logadviser.data.ActivityItem;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AccountMode;
import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.MembershipMode;
import com.logadviser.engine.RankedActivity;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Guards the "Membership" filter: P2P (the default) shows everything, F2P keeps only the
 * free-to-play obtainable slots (f2p_slots.json), so the F2P ranking is a strict subset of the
 * P2P ranking and every slot a ranked F2P activity exposes is itself F2P.
 */
public class MembershipFilterTest
{
	// f2p_slots.json size — bump this when the wiki-sourced F2P list is regenerated
	// (tools/generate_f2p_slots.py), the same way the activity/slot row counts are bumped.
	private static final int F2P_SLOT_COUNT = 101;

	private StaticData data;

	@Before
	public void setUp() throws Exception
	{
		data = StaticDataLoader.loadAll(new Gson());
	}

	private AdviserEngine mainEngine()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);
		engine.setAccountMode(AccountMode.MAIN);
		return engine;
	}

	private static Set<Integer> indices(AdviserEngine engine, MembershipMode mode)
	{
		engine.setMembershipMode(mode);
		Set<Integer> out = new HashSet<>();
		for (RankedActivity r : engine.getRanking())
		{
			out.add(r.getActivity().getIndex());
		}
		return out;
	}

	@Test
	public void f2pSlotSetIsPopulated()
	{
		assertEquals("f2p_slots.json row count changed — regenerate and bump F2P_SLOT_COUNT",
			F2P_SLOT_COUNT, data.getF2pItemIds().size());
	}

	@Test
	public void defaultModeIsP2pAndShowsEverything()
	{
		AdviserEngine engine = mainEngine();
		assertEquals("default membership mode must be P2P (show all)",
			MembershipMode.P2P, engine.getMembershipMode());
		assertFalse("P2P ranking must not be empty", engine.getRanking().isEmpty());
	}

	@Test
	public void f2pIsAStrictSubsetOfP2p()
	{
		AdviserEngine engine = mainEngine();
		Set<Integer> p2p = indices(engine, MembershipMode.P2P);
		Set<Integer> f2p = indices(engine, MembershipMode.F2P);

		assertFalse("P2P ranking must not be empty", p2p.isEmpty());
		assertFalse("F2P ranking must not be empty", f2p.isEmpty());
		assertTrue("every F2P activity must also be in the P2P ranking", p2p.containsAll(f2p));
		assertTrue("F2P must hide some members-only activities", f2p.size() < p2p.size());
	}

	@Test
	public void f2pRankedActivitiesExposeOnlyF2pSlots()
	{
		AdviserEngine engine = mainEngine();
		engine.setMembershipMode(MembershipMode.F2P);
		for (RankedActivity r : engine.getRanking())
		{
			int idx = r.getActivity().getIndex();
			List<ActivityItem> visible = engine.visibleItemsForActivity(idx);
			assertFalse("a ranked F2P activity must keep at least one slot", visible.isEmpty());
			for (ActivityItem it : visible)
			{
				assertTrue("activity " + idx + " exposes non-F2P slot " + it.getItemId() + " in F2P mode",
					data.isF2p(it.getItemId()));
			}
		}
	}

	@Test
	public void knownFreeToPlayBossShowsInF2p()
	{
		// Obor is a free-to-play boss (drops the Hill giant club), so its activity must survive F2P.
		int oborIndex = -1;
		for (Activity a : data.getActivities())
		{
			if (a.getName().toLowerCase().contains("obor"))
			{
				oborIndex = a.getIndex();
				break;
			}
		}
		assertTrue("data should contain the Obor activity", oborIndex >= 0);

		AdviserEngine engine = mainEngine();
		assertTrue("Obor (F2P boss) must appear in the F2P ranking",
			indices(engine, MembershipMode.F2P).contains(oborIndex));
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.ActivityItem;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AccountMode;
import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.RankedActivity;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Guards the "Pets Only" filter: only pet drops are considered, the time is the pet rate (not the
 * whole-table time-to-log), an activity with several pets at once shows the combined shared rate,
 * and pet-mode skips are tracked separately from the normal skip list.
 */
public class PetsOnlyTest
{
	// Single-pet activity: Killing vorkath -> Vorki (1/3000), no competing pet.
	private static final int VORKATH_INDEX = 54;
	private static final int VORKI = 21992;
	private static final double VORKATH_CPH_MAIN = 34.0;

	// Multi-pet activity: Dagannoth Kings drops prime/rex/supreme (each 1/15000) at once.
	private static final int DKS_INDEX = 14;
	private static final double DKS_CPH_MAIN = 105.0;
	private static final double DKS_PET_K = 15000.0;

	// Multi-source pet: Pet chaos elemental drops from chaos elemental (idx 9, faster) and
	// chaos fanatic (idx 10, slower); both unlocked. Dedupe must keep the chaos-elemental row.
	private static final int PET_CHAOS_ELEMENTAL = 11995;
	private static final int CHAOS_ELEMENTAL_INDEX = 9;
	private static final double CHAOS_ELEMENTAL_CPH_MAIN = 120.0;
	private static final double CHAOS_ELEMENTAL_PET_K = 300.0;

	// Locked-only multi-source pet: Tumeken's guardian only drops from the ToA reward chests, which
	// all require progress; with empty progress every source is locked. Fastest locked = ToA 500.
	private static final int TUMEKENS_GUARDIAN = 27352;
	private static final int TOA_500_INDEX = 66;

	private StaticData data;

	@Before
	public void setUp() throws Exception
	{
		data = StaticDataLoader.loadAll(new Gson());
	}

	private AdviserEngine mainEngine()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);
		engine.setAccountMode(AccountMode.MAIN);
		return engine;
	}

	@Test
	public void petsJsonHasThePetSetAndEveryIdIsAKnownSlot()
	{
		assertEquals("pets.json should hold the canonical OSRS pet set", 71, data.getPetItemIds().size());
		for (int id : data.getPetItemIds())
		{
			assertTrue("pet id " + id + " must map to a real collection-log slot",
				data.slotsByItemId().containsKey(id));
			assertTrue("isPet must agree with the set for " + id, data.isPet(id));
		}
	}

	@Test
	public void everyRankedActivityInPetsModeIsTimedAgainstAPet()
	{
		AdviserEngine engine = mainEngine();
		engine.setPetsOnly(true);

		List<RankedActivity> ranking = engine.getRanking();
		assertFalse("pets mode should rank the activities that still drop a pet", ranking.isEmpty());
		for (RankedActivity r : ranking)
		{
			ActivityItem display = r.getDisplayItem();
			assertNotNull("a ranked pet activity must have a display item", display);
			assertTrue("the display item must be a pet (" + display.getItemName() + ")",
				data.isPet(display.getItemId()));
		}
	}

	@Test
	public void singlePetActivityTimeIsThePetRateAlone()
	{
		AdviserEngine engine = mainEngine();
		engine.setPetsOnly(true);

		RankedActivity vorkath = find(engine.getRanking(), VORKATH_INDEX);
		assertNotNull("Vorkath should appear while Vorki is uncollected", vorkath);
		assertEquals("display item must be the pet", VORKI, vorkath.getDisplayItem().getItemId());

		double expected = 3000.0 / VORKATH_CPH_MAIN; // Vorki 1/3000, extraTimeFirst 0
		assertEquals("time-to-pet must be the pet's own rate, not the whole-table time-to-log",
			expected, vorkath.getTimeToNextSlotHours(), expected * 1e-6);
	}

	@Test
	public void dagannothKingsShowsOneRowAtTheCombinedSharedRate()
	{
		AdviserEngine engine = mainEngine();
		engine.setPetsOnly(true);

		List<RankedActivity> ranking = engine.getRanking();
		int dksRows = 0;
		for (RankedActivity r : ranking)
		{
			if (r.getActivity().getIndex() == DKS_INDEX)
			{
				dksRows++;
			}
		}
		assertEquals("Dagannoth Kings must appear exactly once", 1, dksRows);

		RankedActivity dks = find(ranking, DKS_INDEX);
		assertNotNull(dks);
		// Three 1/15000 pets in the harmonic "Neither" bucket combine to 1/5000 per kill.
		double shared = (DKS_PET_K / 3.0) / DKS_CPH_MAIN;
		double single = DKS_PET_K / DKS_CPH_MAIN;
		assertEquals("DKS must use the combined shared pet rate (all three at once)",
			shared, dks.getTimeToNextSlotHours(), shared * 1e-6);
		assertTrue("shared rate must be faster than chasing a single dagannoth pet",
			dks.getTimeToNextSlotHours() < single);
	}

	@Test
	public void activityLeavesPetsRankingOnceItsOnlyPetIsObtained()
	{
		AdviserEngine engine = mainEngine();
		engine.setPetsOnly(true);
		assertNotNull("Vorkath present before obtaining Vorki", find(engine.getRanking(), VORKATH_INDEX));

		engine.markObtained(VORKI);
		assertNull("Vorkath must drop out once its only pet is collected", find(engine.getRanking(), VORKATH_INDEX));
	}

	@Test
	public void togglingPetsOffRestoresTheNormalRanking()
	{
		AdviserEngine engine = mainEngine();
		int normalSize = engine.getRanking().size();

		engine.setPetsOnly(true);
		int petSize = engine.getRanking().size();
		assertTrue("pets mode should be a strict subset of the full ranking", petSize < normalSize);

		engine.setPetsOnly(false);
		assertEquals("turning pets mode off restores the normal ranking", normalSize, engine.getRanking().size());
	}

	@Test
	public void petSkipsAreSeparateFromNormalSkips()
	{
		AdviserEngine engine = mainEngine();

		// Skip DKS in the normal mode.
		engine.skip(DKS_INDEX);
		assertTrue(engine.skippedActivities().contains(DKS_INDEX));
		assertTrue("normal skip must not leak into the pet skip list", engine.petsSkippedActivities().isEmpty());

		// Switch to pets mode and skip Vorkath there.
		engine.setPetsOnly(true);
		engine.skip(VORKATH_INDEX);
		assertTrue("pet skip recorded in the pet list", engine.petsSkippedActivities().contains(VORKATH_INDEX));
		assertFalse("pet skip must not leak into the normal list", engine.skippedActivities().contains(VORKATH_INDEX));
		assertEquals("normal skip list untouched while in pets mode", 1, engine.skippedActivities().size());

		// In pets mode the normal-skipped DKS is still shown (it has pets); the pet-skipped Vorkath is hidden.
		assertNotNull("DKS is only normal-skipped, so it still appears in pets mode", find(engine.getRanking(), DKS_INDEX));
		assertNull("Vorkath is pet-skipped, so it is hidden in pets mode", find(engine.getRanking(), VORKATH_INDEX));
	}

	@Test
	public void everyPetAppearsAtMostOnce()
	{
		AdviserEngine engine = mainEngine();
		engine.setPetsOnly(true);

		java.util.Set<Integer> seen = new java.util.HashSet<>();
		for (RankedActivity r : engine.getRanking())
		{
			int petId = r.getDisplayItem().getItemId();
			assertTrue("pet " + r.getDisplayItem().getItemName() + " is listed more than once", seen.add(petId));
		}
	}

	@Test
	public void multiSourcePetCollapsesToFastestUnlockedSource()
	{
		AdviserEngine engine = mainEngine();
		engine.setPetsOnly(true);

		List<RankedActivity> ranking = engine.getRanking();
		int rows = 0;
		for (RankedActivity r : ranking)
		{
			if (r.getDisplayItem().getItemId() == PET_CHAOS_ELEMENTAL)
			{
				rows++;
			}
		}
		assertEquals("Pet chaos elemental must collapse to a single row", 1, rows);

		RankedActivity row = find(ranking, CHAOS_ELEMENTAL_INDEX);
		assertNotNull("the kept source must be the faster chaos-elemental kill", row);
		assertEquals(PET_CHAOS_ELEMENTAL, row.getDisplayItem().getItemId());
		double expected = CHAOS_ELEMENTAL_PET_K / CHAOS_ELEMENTAL_CPH_MAIN;
		assertEquals(expected, row.getTimeToNextSlotHours(), expected * 1e-6);
		assertNull("the slower chaos-fanatic source must be deduped away", find(ranking, 10));
	}

	@Test
	public void lockedOnlyPetIsShownOnceAsLocked()
	{
		AdviserEngine engine = mainEngine(); // empty player progress -> ToA is locked
		engine.setPetsOnly(true);

		List<RankedActivity> ranking = engine.getRanking();
		int rows = 0;
		for (RankedActivity r : ranking)
		{
			if (r.getDisplayItem().getItemId() == TUMEKENS_GUARDIAN)
			{
				rows++;
			}
		}
		assertEquals("Tumeken's guardian must appear exactly once", 1, rows);

		RankedActivity row = find(ranking, TOA_500_INDEX);
		assertNotNull("kept source must be the fastest (ToA 500) reward chest", row);
		assertEquals(TUMEKENS_GUARDIAN, row.getDisplayItem().getItemId());
		assertTrue("a pet with no unlocked source must be shown as locked", row.isLocked());
	}

	private static RankedActivity find(List<RankedActivity> ranking, int activityIndex)
	{
		for (RankedActivity r : ranking)
		{
			if (r.getActivity().getIndex() == activityIndex)
			{
				return r;
			}
		}
		return null;
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.RankedActivity;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Covers skip/unskip and the skip-list view that backs the panel's
 * "View skip list" / "Skip selected" buttons — no RuneLite client involved.
 */
public class SkipRankingTest
{
	private StaticData data;

	@Before
	public void setUp() throws Exception
	{
		data = StaticDataLoader.loadAll(new Gson());
	}

	@Test
	public void skippedActivitiesLeaveRankingAndAppearInSkipList()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);

		List<RankedActivity> before = engine.getRanking();
		assertTrue("need at least two rankable activities to test", before.size() >= 2);
		int idxA = before.get(0).getActivity().getIndex();
		int idxB = before.get(1).getActivity().getIndex();

		engine.skip(idxA);
		engine.skip(idxB);

		assertFalse("skipped A must drop out of the ranking", contains(engine.getRanking(), idxA));
		assertFalse("skipped B must drop out of the ranking", contains(engine.getRanking(), idxB));

		List<RankedActivity> skipped = engine.getSkippedRanking();
		assertEquals(2, skipped.size());
		assertTrue(contains(skipped, idxA));
		assertTrue(contains(skipped, idxB));
	}

	@Test
	public void unskipReversesASingleActivity()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);

		List<RankedActivity> before = engine.getRanking();
		int idxA = before.get(0).getActivity().getIndex();
		int idxB = before.get(1).getActivity().getIndex();
		engine.skip(idxA);
		engine.skip(idxB);

		engine.unskip(idxA);

		assertTrue("unskipped A must return to the ranking", contains(engine.getRanking(), idxA));
		assertFalse("A must be gone from the skip list", contains(engine.getSkippedRanking(), idxA));
		assertTrue("B must still be skipped", contains(engine.getSkippedRanking(), idxB));
		assertEquals(1, engine.getSkippedRanking().size());

		// Unskipping something that was never skipped is a harmless no-op.
		engine.unskip(idxA);
		assertEquals(1, engine.getSkippedRanking().size());
	}

	private static boolean contains(List<RankedActivity> ranking, int activityIndex)
	{
		for (RankedActivity r : ranking)
		{
			if (r.getActivity().getIndex() == activityIndex)
			{
				return true;
			}
		}
		return false;
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AccountMode;
import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.RankedActivity;
import com.logadviser.engine.ShowFilter;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Guards the multi-select "Show" filter and the new "Slayer" option: SLAYER returns exactly the
 * activities with a Slayer-level requirement minus the boat-combat bounty tasks, ticked options are
 * unioned, and an empty selection means "All".
 */
public class SlayerFilterTest
{
	// Boat-combat *bounty*-task entries: they carry a Slayer requirement but are not slayer tasks,
	// so the Slayer filter must exclude them.
	private static final int GREAT_WHITE_SHARK_INDEX = 144;
	private static final int LAVA_STRYKEWYRM_INDEX = 254;

	private StaticData data;

	@Before
	public void setUp() throws Exception
	{
		data = StaticDataLoader.loadAll(new Gson());
	}

	private AdviserEngine mainEngine()
	{
		AdviserEngine engine = new AdviserEngine(data, () -> false);
		engine.setAccountMode(AccountMode.MAIN);
		return engine;
	}

	private static Set<Integer> indices(AdviserEngine engine, EnumSet<ShowFilter> filter)
	{
		engine.setShowFilter(filter);
		Set<Integer> out = new HashSet<>();
		for (RankedActivity r : engine.getRanking())
		{
			out.add(r.getActivity().getIndex());
		}
		return out;
	}

	private boolean isSlayer(int activityIndex, String name)
	{
		return data.requirementsFor(activityIndex).getSkillLevels().containsKey(Skill.SLAYER)
			&& !name.toLowerCase().contains("bounty task");
	}

	@Test
	public void slayerFilterReturnsExactlyTheSlayerActivities()
	{
		AdviserEngine engine = mainEngine();

		// Derive the expected slayer set from the unfiltered ranking using the same data rule.
		Set<Integer> expected = new HashSet<>();
		engine.setShowFilter(EnumSet.noneOf(ShowFilter.class));
		for (RankedActivity r : engine.getRanking())
		{
			if (isSlayer(r.getActivity().getIndex(), r.getActivity().getName()))
			{
				expected.add(r.getActivity().getIndex());
			}
		}
		assertFalse("there should be slayer activities in the table", expected.isEmpty());

		Set<Integer> actual = indices(engine, EnumSet.of(ShowFilter.SLAYER));
		assertEquals("Slayer filter must return exactly the slayer activities", expected, actual);
	}

	@Test
	public void slayerFilterExcludesBoatCombatBountyTasks()
	{
		AdviserEngine engine = mainEngine();
		engine.setShowFilter(EnumSet.of(ShowFilter.SLAYER));

		assertNull("great white shark (boat bounty) must not show under Slayer",
			find(engine.getRanking(), GREAT_WHITE_SHARK_INDEX));
		assertNull("lava strykewyrm (boat bounty) must not show under Slayer",
			find(engine.getRanking(), LAVA_STRYKEWYRM_INDEX));
	}

	@Test
	public void tickedOptionsAreUnioned()
	{
		AdviserEngine engine = mainEngine();

		Set<Integer> miscOnly = indices(engine, EnumSet.of(ShowFilter.MISCELLANEOUS));
		Set<Integer> slayerOnly = indices(engine, EnumSet.of(ShowFilter.SLAYER));
		Set<Integer> union = indices(engine, EnumSet.of(ShowFilter.MISCELLANEOUS, ShowFilter.SLAYER));

		assertFalse("misc set should be non-empty", miscOnly.isEmpty());
		assertFalse("slayer set should be non-empty", slayerOnly.isEmpty());

		Set<Integer> expectedUnion = new HashSet<>(miscOnly);
		expectedUnion.addAll(slayerOnly);
		assertEquals("Misc + Slayer must be the union of the two", expectedUnion, union);
	}

	@Test
	public void emptySelectionMeansAll()
	{
		AdviserEngine engine = mainEngine();

		// Every activity has exactly one category, so the three categories together cover the
		// whole table — equal to the empty ("All") selection.
		int allSize = indices(engine, EnumSet.noneOf(ShowFilter.class)).size();
		int allCategoriesSize = indices(engine,
			EnumSet.of(ShowFilter.COMBAT, ShowFilter.MINIGAME, ShowFilter.MISCELLANEOUS)).size();

		assertTrue("All should rank something", allSize > 0);
		assertEquals("empty selection must equal selecting every category", allSize, allCategoriesSize);
	}

	private static RankedActivity find(List<RankedActivity> ranking, int activityIndex)
	{
		for (RankedActivity r : ranking)
		{
			if (r.getActivity().getIndex() == activityIndex)
			{
				return r;
			}
		}
		return null;
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.RankedActivity;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Pins the Summer Sweep-Up 2026 elemental jewels and necklace of fangs. Three of the five drops
 * arrive with brand-new activities (260-262); the other two land on tables that already existed,
 * where they become the fastest row and so change an estimate the ranking was already using.
 * Both effects are hand-entered data whose only other check is a row count, so the arithmetic is
 * asserted explicitly here.
 * <p>
 * All five sit in the "neither" bucket — separate rolls on one monster's drop table — so on a
 * shared table their rates combine harmonically rather than the fastest one winning outright.
 */
public class SummerSweepUpDataTest
{
	private static final int TUROTH = 176;
	private static final int INFERNAL_MAGES = 198;
	private static final int MOLANISKS = 260;
	private static final int SEA_SNAKE_HATCHLINGS = 261;
	private static final int KILLERWATTS = 262;

	private static final int NECKLACE_OF_FANGS = 34401;
	private static final int AIR_DIAMOND = 34404;
	private static final int WATER_SAPPHIRE = 34410;
	private static final int EARTH_EMERALD = 34416;
	private static final int FIRE_RUBY = 34422;

	private StaticData data;
	private AdviserEngine engine;

	@Before
	public void setUp() throws Exception
	{
		data = StaticDataLoader.loadAll(new Gson());
		engine = new AdviserEngine(data, () -> false);
		// Gating is covered by ActivityRequirementsTest; here we only care about the math.
		engine.setIgnoreRequirements(true);
	}

	@Test
	public void eachNewActivityIsItsJewelAloneOverTheKillRate()
	{
		// One slot apiece, all at 1/64, so the estimate is just 64 kills at the activity's rate.
		assertSoleJewel(MOLANISKS, EARTH_EMERALD, 300.0);
		assertSoleJewel(SEA_SNAKE_HATCHLINGS, WATER_SAPPHIRE, 560.0);
		assertSoleJewel(KILLERWATTS, AIR_DIAMOND, 400.0);
	}

	@Test
	public void fireRubyBecomesTheInfernalMageEstimate()
	{
		// Was mystic hat + boots (dark), both 1/512, combining to 256 kills at 450/hr. Fire ruby
		// at 1/64 dominates that: the combined attempts drop to 51.2 and it drives the display.
		double combined = 1.0 / (1.0 / 512.0 + 1.0 / 512.0 + 1.0 / 64.0);
		assertEquals(51.2, combined, 1e-9);

		RankedActivity r = find(INFERNAL_MAGES);
		assertEquals(combined / 450.0, r.getTimeToNextSlotHours(), 1e-9);
		assertEquals(FIRE_RUBY, r.getDisplayItem().getItemId());
		assertEquals("the log entry has three items", 3, r.getSlotsTotal());
	}

	@Test
	public void necklaceOfFangsBecomesTheTurothEstimate()
	{
		// Leaf-bladed sword 1/500 and mystic robe bottom (light) 1/512 carried the estimate; the
		// shield left half and dragon spear rows are rare enough to barely move it. At 1/128 the
		// necklace is four times faster than anything already on the table.
		double combined = 1.0 / (1.0 / 500.0 + 1.0 / 512.0 + 1.0 / 104858.0 + 1.0 / 139810.0
			+ 1.0 / 128.0);

		RankedActivity r = find(TUROTH);
		assertEquals(combined / 300.0, r.getTimeToNextSlotHours(), 1e-9);
		assertEquals(NECKLACE_OF_FANGS, r.getDisplayItem().getItemId());
		assertEquals("the log entry has five items", 5, r.getSlotsTotal());
	}

	@Test
	public void obtainingTheJewelRestoresTheOldEstimate()
	{
		// The pre-update estimates must come back once the new row is collected — proves the new
		// rows joined the existing bucket rather than replacing what was there.
		engine.markObtained(FIRE_RUBY);
		assertEquals(256.0 / 450.0, find(INFERNAL_MAGES).getTimeToNextSlotHours(), 1e-9);

		engine.markObtained(NECKLACE_OF_FANGS);
		double turothWas = 1.0 / (1.0 / 500.0 + 1.0 / 512.0 + 1.0 / 104858.0 + 1.0 / 139810.0);
		assertEquals(turothWas / 300.0, find(TUROTH).getTimeToNextSlotHours(), 1e-9);
		assertEquals("four slots left once the necklace is in", 4, find(TUROTH).getSlotsLeft());
	}

	@Test
	public void newSlotNamesResolveFromTheClogChatString()
	{
		// The "New item added to your collection log: X" handler matches on lower-cased slot
		// name, so a typo here silently drops live drops.
		assertEquals(Integer.valueOf(NECKLACE_OF_FANGS), data.itemIdsByName().get("necklace of fangs"));
		assertEquals(Integer.valueOf(AIR_DIAMOND), data.itemIdsByName().get("air diamond"));
		assertEquals(Integer.valueOf(WATER_SAPPHIRE), data.itemIdsByName().get("water sapphire"));
		assertEquals(Integer.valueOf(EARTH_EMERALD), data.itemIdsByName().get("earth emerald"));
		assertEquals(Integer.valueOf(FIRE_RUBY), data.itemIdsByName().get("fire ruby"));
	}

	private void assertSoleJewel(int activityIndex, int itemId, double killsPerHour)
	{
		RankedActivity r = find(activityIndex);
		assertEquals(64.0 / killsPerHour, r.getTimeToNextSlotHours(), 1e-9);
		assertEquals(itemId, r.getDisplayItem().getItemId());
		assertEquals(1, r.getSlotsTotal());
	}

	private RankedActivity find(int activityIndex)
	{
		List<RankedActivity> ranking = engine.getRanking();
		for (RankedActivity r : ranking)
		{
			if (r.getActivity().getIndex() == activityIndex)
			{
				return r;
			}
		}
		throw new AssertionError("activity index " + activityIndex + " not in ranking");
	}
}

package com.logadviser;

import com.google.gson.Gson;
import com.logadviser.data.StaticData;
import com.logadviser.data.StaticDataLoader;
import com.logadviser.engine.AdviserEngine;
import com.logadviser.engine.RankedActivity;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Pins the Wyrmscraig data added for the 29 July 2026 update (activities 257-259). These are
 * hand-entered rows whose only other check is a row count, so the arithmetic that the ranking
 * depends on — attempts / completions-per-hour, and which bucket each drop lands in — is
 * asserted here explicitly.
 * <p>
 * The Mad Angel rates are the wiki's published post-quest figures, measured by its drop-log
 * project over ~3.8M kills; the earlier estimates they replaced were noticeably off.
 */
public class WyrmscraigDataTest
{
	private static final int GOLEM_CRAFTING = 257;
	private static final int GOAT_HUNTING = 258;
	private static final int MAD_ANGEL = 259;

	private StaticData data;
	private AdviserEngine engine;

	@Before
	public void setUp() throws Exception
	{
		data = StaticDataLoader.loadAll(new Gson());
		engine = new AdviserEngine(data, () -> false);
		// Gating is covered by ActivityRequirementsTest; here we only care about the math.
		engine.setIgnoreRequirements(true);
	}

	@Test
	public void golemCraftingIsChiselOverFiftyEightPerHour()
	{
		// Jeweller's chisel at 1/315, 58 golems/hour.
		RankedActivity r = find(GOLEM_CRAFTING);
		assertEquals(315.0 / 58.0, r.getTimeToNextSlotHours(), 1e-6);
		assertEquals(34024, r.getDisplayItem().getItemId());
		assertEquals(1, r.getSlotsTotal());
	}

	@Test
	public void goatHuntingIsMcgrootOverNineHundredPerHour()
	{
		// Mr mcgroot has no published rate; 36000 attempts is a placeholder standing in for
		// roughly 40 hours at 900 catches/hour. Revisit when Jagex or the wiki publishes one.
		RankedActivity r = find(GOAT_HUNTING);
		assertEquals(40.0, r.getTimeToNextSlotHours(), 1e-6);
		assertEquals(34040, r.getDisplayItem().getItemId());
		assertEquals(1, r.getSlotsTotal());
	}

	@Test
	public void madAngelHeadlinesGraniteDustAsAGuaranteedDrop()
	{
		// Granite dust is a 100% drop, so one kill (1/60 h) is the next slot and it wins the
		// exact bucket outright. The other four rows are slower and must not displace it.
		RankedActivity r = find(MAD_ANGEL);
		assertEquals(1.0 / 60.0, r.getTimeToNextSlotHours(), 1e-9);
		assertEquals(21726, r.getDisplayItem().getItemId());
		assertEquals("the log entry has five items", 5, r.getSlotsTotal());
	}

	@Test
	public void madAngelFallsBackToTheCombinedPreRollOnceGraniteDustIsObtained()
	{
		// With Granite dust gone the "neither" bucket decides: the wiki's pre-roll table —
		// Ardeaglais teleport (1/25), Hallowfell (1/128) and Jar of light (1/1000) — is a
		// single mutually-exclusive roll, so the three combine harmonically.
		engine.markObtained(21726);
		double combined = 1.0 / (1.0 / 25.0 + 1.0 / 128.0 + 1.0 / 1000.0);
		RankedActivity r = find(MAD_ANGEL);
		assertEquals(combined / 60.0, r.getTimeToNextSlotHours(), 1e-6);
		assertEquals("four slots left once Granite dust is in", 4, r.getSlotsLeft());
	}

	@Test
	public void bothNewPetsAreKnownSlotsAndFlaggedAsPets()
	{
		for (int petId : new int[]{34040, 34042})
		{
			assertTrue("pet " + petId + " must be flagged a pet", data.isPet(petId));
			assertNotNull("pet " + petId + " must be a known slot",
				data.slotsByItemId().get(petId));
		}
	}

	@Test
	public void newSlotNamesResolveFromTheClogChatString()
	{
		// The "New item added to your collection log: X" handler matches on lower-cased slot
		// name, so a typo here silently drops live drops.
		assertEquals(Integer.valueOf(34024), data.itemIdsByName().get("jeweller's chisel"));
		assertEquals(Integer.valueOf(34027), data.itemIdsByName().get("hallowfell"));
		assertEquals(Integer.valueOf(34030), data.itemIdsByName().get("jar of light"));
		assertEquals(Integer.valueOf(34033), data.itemIdsByName().get("ardeaglais teleport"));
		assertEquals(Integer.valueOf(34040), data.itemIdsByName().get("mr mcgroot"));
		assertEquals(Integer.valueOf(34042), data.itemIdsByName().get("aggy"));
	}

	private RankedActivity find(int activityIndex)
	{
		List<RankedActivity> ranking = engine.getRanking();
		for (RankedActivity r : ranking)
		{
			if (r.getActivity().getIndex() == activityIndex)
			{
				return r;
			}
		}
		throw new AssertionError("activity index " + activityIndex + " not in ranking");
	}
}
